// --- CAR WIZARD ---

const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(CarInsuranceStep.VEHICLE_DATA);
  const [v, setV] = useState<VehicleState>({
    brand: '', isOtherBrand: false, otherBrand: '',
    modelCode: '', isOtherModel: false, otherModel: '',
    year: 2024, price: 0, manualPrice: null,
    plateDetails: { regionCode: '', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { 
      flood: false, earthquake: false, srcc: false, terrorism: false, 
      authorizedWorkshop: false, tpl: 0, paDriver: 0, paPassenger: 0, passengers: 1 
    },
    promoCode: '', discountType: 'PERCENT', discountValue: 0,
    photos: { ktp: null, stnk: null, carFront: null, carBack: null, carLeft: null, carRight: null, interior: null },
    aiScoring: 0, selectedProvider: null
  });

  const [loading, setLoading] = useState(false);
  const [user, setUser] = useState<UserState>({ name: '', ktpNo: '', address: '', email: '', phone: '' });

  const calculatePremium = (provider: any) => {
    const basePrice = v.manualPrice || v.price;
    const region = getRegionFromPlate(v.plateDetails.regionCode);
    const baseRate = getOJKRate(basePrice, region, v.insuranceType);

    let totalRate = baseRate;
    if (v.expansions.authorizedWorkshop) totalRate += 0.2; // 0.2%
    // Add other expansion rates here if needed

    let premium = (totalRate / 100) * (basePrice * 1000000);

    // Apply Discount
    if (v.discountType === 'PERCENT') {
      const disc = Math.min(v.discountValue, 25);
      premium -= (disc / 100) * premium;
    } else {
      const maxDisc = 0.25 * premium;
      premium -= Math.min(v.discountValue, maxDisc);
    }

    const total = premium + STAMP_DUTY + provider.adminFee;
    return { premium, total, commission: premium * 0.25 };
  };

  const handlePhotoUpload = (id: keyof typeof v.photos, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setV(prev => ({ ...prev, photos: { ...prev.photos, [id]: reader.result as string } }));
    reader.readAsDataURL(file);
  };

  const handleAIScore = async () => {
    setLoading(true);
    const photosToVerify = Object.entries(v.photos)
      .filter(([key, val]) => val !== null)
      .map(([key, val]) => ({ label: key, base64: val as string }));

    const res = await analyzeVehicleVerification(photosToVerify);
    setLoading(false);
    if (res.success && res.data) {
      setV(prev => ({ ...prev, aiScoring: res.data!.overallScore }));
      setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    }
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      {/* Header */}
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-2 dark:text-gray-400 text-gray-600"><ChevronLeft/></button>
        <div className="flex-1">
          <h2 className="text-xl font-black uppercase text-gray-900 dark:text-white">Smart <span className="text-primary-500">Auto</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-1 rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 transition-all duration-500" style={{ width: `${(step/8)*100}%` }}></div>
          </div>
        </div>
      </div>

      {step === CarInsuranceStep.VEHICLE_DATA && (
        <div className="space-y-6 animate-fade-in">
          <div className="space-y-4">
            <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest ml-1">Step 1: Vehicle Data</p>

            {/* Brand Selection */}
            <div className="grid grid-cols-2 gap-3">
              {['TOYOTA', 'HONDA', 'BMW', 'OTHERS'].map(b => (
                <button 
                  key={b} 
                  onClick={() => setV({...v, brand: b, isOtherBrand: b === 'OTHERS'})}
                  className={`p-4 glass-card rounded-2xl border-2 transition-all font-black text-xs uppercase ${v.brand === b ? 'border-primary-500 text-primary-500' : 'border-transparent dark:text-white text-gray-900'}`}
                >
                  {b}
                </button>
              ))}
            </div>
            {v.isOtherBrand && (
              <input 
                placeholder="Enter Brand Name" 
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5"
                onChange={e => setV({...v, otherBrand: e.target.value})}
              />
            )}

            {/* Model Selection */}
            {!v.isOtherBrand ? (
              <select 
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5 font-bold"
                onChange={e => {
                  const m = CAR_DATABASE.find(c => c.code === e.target.value);
                  if (m) setV({...v, modelCode: m.code, price: m.yearPrices[v.year] || 0});
                }}
              >
                <option value="">Select Model</option>
                {CAR_DATABASE.filter(c => c.brand === v.brand).map(m => (
                  <option key={m.code} value={m.code}>{m.modelName}</option>
                ))}
              </select>
            ) : (
              <input 
                placeholder="Enter Model Name" 
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5"
                onChange={e => setV({...v, otherModel: e.target.value})}
              />
            )}

            {/* Price Input */}
            <div className="space-y-1">
              <label className="text-[0.55rem] font-black text-gray-500 uppercase tracking-widest ml-2">Vehicle Price (Millions)</label>
              <input 
                type="number" 
                placeholder="Enter Price" 
                value={v.manualPrice || v.price || ''}
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5 font-bold"
                onChange={e => {
                  const val = parseFloat(e.target.value);
                  setV({...v, manualPrice: val});
                }}
              />
            </div>

            {/* Plate Number */}
            <div className="grid grid-cols-3 gap-2">
              <input placeholder="AA" maxLength={2} className="p-4 glass-card rounded-xl text-center font-bold" value={v.plateDetails.regionCode} onChange={e => setV({...v, plateDetails: {...v.plateDetails, regionCode: e.target.value.toUpperCase()}})} />
              <input placeholder="BBBB" maxLength={4} className="p-4 glass-card rounded-xl text-center font-bold" value={v.plateDetails.number} onChange={e => setV({...v, plateDetails: {...v.plateDetails, number: e.target.value}})} />
              <input placeholder="CCC" maxLength={3} className="p-4 glass-card rounded-xl text-center font-bold" value={v.plateDetails.suffix} onChange={e => setV({...v, plateDetails: {...v.plateDetails, suffix: e.target.value.toUpperCase()}})} />
            </div>

            {/* Usage & Condition */}
            <div className="grid grid-cols-2 gap-3">
              <select className="p-4 glass-card rounded-xl font-bold" onChange={e => setV({...v, usage: e.target.value as any})}>
                <option value="PERSONAL">Personal</option>
                <option value="COMMERCIAL">Commercial</option>
                <option value="DINAS">Service (Dinas)</option>
              </select>
              <select className="p-4 glass-card rounded-xl font-bold" onChange={e => setV({...v, condition: e.target.value as any})}>
                <option value="NEW">New</option>
                <option value="USED">Used</option>
              </select>
            </div>
          </div>
          <button onClick={() => setStep(CarInsuranceStep.COVERAGE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl">Choose Coverage</button>
        </div>
      )}

      {step === CarInsuranceStep.COVERAGE && (
        <div className="space-y-6 animate-fade-in">
          <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest ml-1">Step 2: Coverage & Promos</p>

          <div className="grid grid-cols-2 gap-3">
            {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(t => (
              <button 
                key={t} 
                onClick={() => setV({...v, insuranceType: t})}
                className={`p-6 glass-card rounded-3xl border-2 transition-all ${v.insuranceType === t ? 'border-primary-500' : 'border-transparent'}`}
              >
                <p className="font-black dark:text-white text-gray-900 uppercase text-sm">{t}</p>
              </button>
            ))}
          </div>

          <div className="space-y-4">
            <label className="flex items-center gap-3 p-4 glass-card rounded-xl cursor-pointer">
              <input type="checkbox" className="w-5 h-5 accent-primary-500" onChange={e => setV({...v, expansions: {...v.expansions, authorizedWorkshop: e.target.checked}})} />
              <div className="flex-1">
                <p className="text-xs font-black uppercase">Authorized Workshop (+0.2%)</p>
                <p className="text-[0.5rem] text-gray-500 uppercase font-bold tracking-widest">Repair at official brand workshops</p>
              </div>
            </label>
            {/* Additional expansions could be added here */}
          </div>

          <div className="space-y-3">
            <input placeholder="Promo Code" className="w-full p-4 glass-card rounded-xl border border-black/5" onChange={e => setV({...v, promoCode: e.target.value})} />
            <div className="flex gap-2">
              <select className="p-4 glass-card rounded-xl font-bold text-xs" onChange={e => setV({...v, discountType: e.target.value as any})}>
                <option value="PERCENT">%</option>
