              <input type="number" placeholder="Discount Value" className="flex-1 p-4 glass-card rounded-xl" onChange={e => setV({...v, discountValue: parseFloat(e.target.value) || 0})} />
            </div>
          </div>

          <button onClick={() => setStep(CarInsuranceStep.INSURANCE_CHOICE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl">Compare Insurers</button>
        </div>
      )}

      {step === CarInsuranceStep.INSURANCE_CHOICE && (
        <div className="space-y-6 animate-fade-in">
          <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest ml-1">Step 3: Select Provider</p>
          <div className="grid gap-4">
            {INSURANCE_PROVIDERS.map(prov => {
              const { premium, total, commission } = calculatePremium(prov);
              return (
                <button 
                  key={prov.id}
                  onClick={() => setV({...v, selectedProvider: prov})}
                  className={`p-6 glass-card rounded-[2.5rem] border-2 text-left relative overflow-hidden group transition-all ${v.selectedProvider?.id === prov.id ? 'border-primary-500 bg-primary-500/5' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500">
                        <prov.logo size={24}/>
                      </div>
                      <div>
                        <p className="font-black dark:text-white text-gray-900 uppercase text-base">{prov.name}</p>
                        <div className="flex items-center gap-1">
                          <Star size={10} className="fill-amber-500 text-amber-500"/>
                          <span className="text-[0.55rem] font-black text-gray-400 uppercase">{prov.rating} Score</span>
                        </div>
                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-[0.5rem] font-black text-gray-400 uppercase tracking-widest">Premium</p>
                      <p className="text-lg font-black text-primary-500">{formatIDR(premium)}</p>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 gap-4 mb-4">
