const TravelWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [travel, setTravel] = useState({
    region: 'INTERNATIONAL' as TravelRegion,
    destination: '',
    startDate: '',
    endDate: '',
    travelerType: 'INDIVIDUAL',
    adults: 1,
    children: 0,
    plan: null as TravelPlanType | null,
    provider: null as any,
    paymentMethod: null as string | null
  });

  const getDays = () => {
    if (!travel.startDate || !travel.endDate) return 0;
    const s = new Date(travel.startDate);
    const e = new Date(travel.endDate);
    const diffTime = Math.abs(e.getTime() - s.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
  };

  const calculatePremium = (planType: TravelPlanType) => {
    const days = getDays();
    const regionKey = travel.region as keyof typeof TRAVEL_PRICING;
    const typeKey = travel.travelerType === 'FAMILY' ? 'FAMILY' : 'INDIVIDUAL';
    const pricingTable = (TRAVEL_PRICING[regionKey] as any)[typeKey];

    if (!pricingTable) return 0;

    const band = pricingTable.find((p: any) => days <= p.maxDays) || pricingTable[pricingTable.length - 1];
    return band.rates[planType] || 0;
  };

  const getPlanList = () => {
    if (travel.region === 'INTERNATIONAL') return ['PLATINUM', 'GOLD', 'ASIA_EXTRA'] as TravelPlanType[];
    return ['GARUDA_1', 'GARUDA_2'] as TravelPlanType[];
  };

  const handleProcessPayment = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setStep(7);
    }, 2000);
  };

  const renderSummary = () => {
    const premium = travel.plan ? calculatePremium(travel.plan) : 0;
    const total = premium + STAMP_DUTY + (travel.provider?.adminFee || 0);

    return (
      <div className="space-y-6 animate-fade-in">
        <div className="p-8 glass-card rounded-[3rem] border border-black/5 dark:border-white/5 space-y-6">
          <div className="flex items-center justify-between">
            <h3 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">Review <span className="text-primary-500">Trip</span></h3>
            <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500">
               <ReceiptText size={24}/>
            </div>
          </div>

          <div className="space-y-4">
             <div className="flex justify-between items-center">
               <span className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest">Plan & Provider</span>
               <span className="text-xs font-black dark:text-white text-gray-900 uppercase">{travel.plan?.replace('_', ' ')} by {travel.provider?.name}</span>
             </div>
             <div className="flex justify-between items-center">
               <span className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest">Destination</span>
               <span className="text-xs font-black dark:text-white text-gray-900 uppercase">{travel.destination}</span>
             </div>
             <div className="flex justify-between items-center">
               <span className="text-[0.6rem] font-black text-gray-500 uppercase tracking-widest">Duration</span>
               <span className="text-xs font-black dark:text-white text-gray-900 uppercase">{getDays()} Days</span>
             </div>
             <div className="pt-4 border-t border-black/5 dark:border-white/5 space-y-3">
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase tracking-widest">
                  <span>Base Premium</span>
                  <span className="dark:text-white text-gray-900">{formatIDR(premium)}</span>
                </div>
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase tracking-widest">
                  <span>Stamp Duty</span>
                  <span className="dark:text-white text-gray-900">{formatIDR(STAMP_DUTY)}</span>
                </div>
                <div className="flex justify-between text-xs font-bold text-gray-500 uppercase tracking-widest">
                  <span>Admin Fee</span>
                  <span className="dark:text-white text-gray-900">{formatIDR(travel.provider?.adminFee || 0)}</span>
                </div>
                <div className="pt-3 flex justify-between items-center border-t border-black/5 dark:border-white/5">
                   <span className="text-[0.7rem] font-black text-primary-500 uppercase tracking-widest">Total Payment</span>
                   <span className="text-2xl font-black dark:text-white text-gray-900 tracking-tighter">{formatIDR(total)}</span>
                </div>
             </div>
          </div>
        </div>

        <button 
          onClick={() => setStep(6)}
          className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase text-sm shadow-2xl flex items-center justify-center gap-3"
        >
          Select Payment Method <ChevronRight size={18}/>
        </button>
      </div>
    );
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-2 dark:text-gray-400 text-gray-600">
          <ChevronLeft/>
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-black uppercase text-gray-900 dark:text-white">Global <span className="text-primary-500">Travel</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-1 rounded-full overflow-hidden">
