const ClaimScreen = ({ onBack }: { onBack: () => void }) => {
  const [image, setImage] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
        analyze(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const analyze = async (base64: string) => {
    setLoading(true);
    const res = await analyzeClaimPhoto(base64);
    setLoading(false);
    if (res.success && res.data) setResult(res.data);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="p-2 dark:text-gray-400 text-gray-600"><ChevronLeft/></button>
        <h2 className="text-2xl font-black uppercase text-gray-900 dark:text-white">Neural <span className="text-primary-500">Claim</span></h2>
      </div>

      {!result ? (
        <div className="aspect-square glass-card rounded-[3rem] border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center p-12 text-center relative overflow-hidden">
          {loading ? (
            <div className="flex flex-col items-center gap-4">
              <Loader2 size={40} className="animate-spin text-primary-500" />
            </div>
          ) : (
            <>
              <Camera size={48} className="text-primary-500 mb-4" />
              <p className="font-black dark:text-white text-gray-900 uppercase">Damage Photo</p>
              <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
            </>
          )}
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white">
            <h3 className="text-3xl font-black">{formatIDR(result.totalEstimasi)}</h3>
          </div>
          <button onClick={() => setResult(null)} className="w-full py-5 glass-card rounded-2xl font-black uppercase text-[0.7rem]">New Analysis</button>
        </div>
      )}
    </div>
  );
};

