const TravelWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [travel, setTravel] = useState({
    region: 'INTERNATIONAL' as TravelRegion,
    destination: '',
    startDate: '',
    endDate: '',
    travelerType: 'INDIVIDUAL',
    adults: 1,
    children: 0,
    plan: null as TravelPlanType | null,
    provider: null as any,
    paymentMethod: null as string | null
  });

  const getDays = () => {
    if (!travel.startDate || !travel.endDate) return 0;
    const s = new Date(travel.startDate);
    const e = new Date(travel.endDate);
    const diffTime = Math.abs(e.getTime() - s.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
  };

  const calculatePremium = (planType: TravelPlanType) => {
    const days = getDays();
    const regionKey = travel.region as keyof typeof TRAVEL_PRICING;
    const typeKey = travel.travelerType === 'FAMILY' ? 'FAMILY' : 'INDIVIDUAL';
    const pricingTable = (TRAVEL_PRICING[regionKey] as any)[typeKey];

    if (!pricingTable) return 0;

    const band = pricingTable.find((p: any) => days <= p.maxDays) || pricingTable[pricingTable.length - 1];
    return band.rates[planType] || 0;
  };

  const getPlanList = () => {
    if (travel.region === 'INTERNATIONAL') return ['PLATINUM', 'GOLD', 'ASIA_EXTRA'] as TravelPlanType[];
    return ['GARUDA_1', 'GARUDA_2'] as TravelPlanType[];
  };

  const handleProcessPayment = () => {
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setStep(7);
    }, 2000);
  };

  const renderSummary = () => {
    const premium = travel.plan ? calculatePremium(travel.plan) : 0;
