const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(CarInsuranceStep.VEHICLE_DATA);
  const [v, setV] = useState<VehicleState>({
    brand: '', isOtherBrand: false, otherBrand: '',
    modelCode: '', isOtherModel: false, otherModel: '',
    year: 2024, price: 0, manualPrice: null,
    plateDetails: { regionCode: '', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { 
      flood: false, earthquake: false, srcc: false, terrorism: false, 
      authorizedWorkshop: false, paDriver: false, paPassenger: false, tpl: 0 
    },
    promoCode: '', discountType: 'PERCENT', discountValue: 0,
    photos: { ktp: null, stnk: null, carFront: null, carBack: null, carLeft: null, carRight: null, interior: null },
    aiScoring: 0, selectedProvider: null
  });

  const [loading, setLoading] = useState(false);
  const [user, setUser] = useState<UserState>({ 
    name: '', ktpNo: '', address: '', email: '', phone: '', policyDelivery: 'WHATSAPP' 
  });

  const calculatePremium = (provider: any) => {
    const basePrice = v.manualPrice || v.price; // in Millions
    const region = getRegionFromPlate(v.plateDetails.regionCode);
    const baseRate = getOJKRate(basePrice, region, v.insuranceType);

    let totalRate = baseRate;
    if (v.expansions.authorizedWorkshop) totalRate += 0.2; // +0.2%

    // Expansion rates addition (simplified approximation for demo)
    if (v.expansions.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (v.expansions.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;
    if (v.expansions.srcc) totalRate += EXPANSION_RATES.SRCC;
    if (v.expansions.terrorism) totalRate += EXPANSION_RATES.TERRORISM;

    let premium = (totalRate / 100) * (basePrice * 1000000);

    // Add TPL (Fixed amounts per level)
    premium += v.expansions.tpl * 10000; // Simplified scale

    // Apply Discount (Max 25%)
    let discount = 0;
    if (v.discountType === 'PERCENT') {
      const pct = Math.min(v.discountValue, 25);
      discount = (pct / 100) * premium;
    } else {
      discount = Math.min(v.discountValue, 0.25 * premium);
    }

    const finalPremium = premium - discount;
    const commission = finalPremium * 0.25; // 25% max
    const total = finalPremium + STAMP_DUTY + provider.adminFee;

    return { 
      basePremium: premium, 
      discount, 
      finalPremium, 
      commission, 
      total, 
      coins: finalPremium * provider.extraCoins 
    };
  };

  const handlePhotoUpload = (id: keyof typeof v.photos, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setV(prev => ({ ...prev, photos: { ...prev.photos, [id]: reader.result as string } }));
    reader.readAsDataURL(file);
  };

  const runAIScore = async () => {
    setLoading(true);
    // Simulate complex matrix verification
    const imagesToVerify = Object.entries(v.photos)
      .filter(([key, val]) => val !== null)
      .map(([key, val]) => ({ label: key, base64: val as string }));

    const res = await analyzeVehicleVerification(imagesToVerify);
    setLoading(false);

    if (res.success && res.data) {
      setV(prev => ({ ...prev, aiScoring: res.data!.overallScore }));
      setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    } else {
      // Demo fallback if API fails
      setV(prev => ({ ...prev, aiScoring: 85 }));
      setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    }
  };

