            <div className="space-y-1">
               <label className="text-[0.55rem] font-black text-gray-500 uppercase tracking-widest ml-2">License Plate</label>
               <div className="grid grid-cols-4 gap-2">
                  <input placeholder="AA" maxLength={2} className="p-4 glass-card rounded-xl text-center font-bold uppercase" value={v.plateDetails.regionCode} onChange={e => setV({...v, plateDetails: {...v.plateDetails, regionCode: e.target.value.toUpperCase()}})} />
                  <input placeholder="8888" maxLength={4} className="col-span-2 p-4 glass-card rounded-xl text-center font-bold" value={v.plateDetails.number} onChange={e => setV({...v, plateDetails: {...v.plateDetails, number: e.target.value}})} />
