               </div>
               {v.plateDetails.regionCode && (
                 <p className="text-[0.5rem] font-bold text-primary-500 uppercase ml-2 mt-1">OJK ZONE: {getRegionFromPlate(v.plateDetails.regionCode)}</p>
               )}
            </div>

            <div className="grid grid-cols-2 gap-3">
               <div className="space-y-1">
                  <label className="text-[0.55rem] font-black text-gray-500 uppercase tracking-widest ml-2">Usage</label>
                  <select className="w-full p-4 glass-card rounded-xl font-bold" value={v.usage} onChange={e => setV({...v, usage: e.target.value as any})}>
