const ClaimScreen = ({ onBack }: { onBack: () => void }) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const res = await analyzeClaimPhoto(reader.result as string);
        if (res.success && res.data) setResult(res.data);
        setLoading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="p-6 max-w-lg mx-auto animate-fade-in pb-32">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="p-2 text-gray-600 hover:text-primary-500"><ChevronLeft/></button>
        <h2 className="text-2xl font-black uppercase tracking-tighter">Neural <span className="text-primary-500">Claim</span></h2>
      </div>
      {!result ? (
        <div className="aspect-square glass-card rounded-[3rem] border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center p-12 text-center relative overflow-hidden">
          {loading ? <Loader2 size={40} className="animate-spin text-primary-500" /> : <Camera size={48} className="text-primary-500 mb-4" />}
          <p className="font-black uppercase text-gray-900 dark:text-white">Foto Kerusakan</p>
          <p className="text-[0.6rem] text-gray-400 mt-2 uppercase">AI akan menghitung estimasi biaya secara otomatis</p>
          <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer" />
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white shadow-xl">
            <p className="text-xs uppercase font-bold opacity-80">Estimasi Perbaikan</p>
            <h3 className="text-3xl font-black">{formatIDR(result.totalEstimasi)}</h3>
            <p className="mt-2 text-sm opacity-90">{result.aiInsight}</p>
          </div>
          <button onClick={() => setResult(null)} className="w-full py-5 glass-card rounded-2xl font-black uppercase text-[0.7rem] dark:text-white text-gray-900 border border-black/5">Analisa Baru</button>
        </div>
      )}
    </div>
  );
};

