                    <div className="flex items-center gap-2">
                       <div className="px-2 py-1 bg-amber-500/10 rounded-full flex items-center gap-1">
                          <Coins size={10} className="text-amber-500"/>
                          <span className="text-[0.55rem] font-black text-amber-600">+{prov.extraCoins * 100}% Path Coins</span>
