const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(CarInsuranceStep.VEHICLE_DATA);
  const [v, setV] = useState<VehicleState>({
    brand: '', isOtherBrand: false, otherBrand: '',
    modelCode: '', isOtherModel: false, otherModel: '',
    year: 2024, price: 0, manualPrice: null,
    plateDetails: { regionCode: '', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { 
      flood: false, earthquake: false, srcc: false, terrorism: false, 
      authorizedWorkshop: false, paDriver: false, paPassenger: false, tpl: 0 
    },
    promoCode: '', discountType: 'PERCENT', discountValue: 0,
    photos: { ktp: null, stnk: null, carFront: null, carBack: null, carLeft: null, carRight: null, interior: null },
    aiScoring: 0, selectedProvider: null
  });

  const [loading, setLoading] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const [loadStatus, setLoadStatus] = useState('Initializing Audit');
  const [user, setUser] = useState<UserState>({ 
    name: '', ktpNo: '', address: '', email: '', phone: '', policyDelivery: 'WHATSAPP' 
  });

  const calculatePremium = (provider: Provider) => {
    const basePrice = v.manualPrice || v.price; 
    const region = getRegionFromPlate(v.plateDetails.regionCode);
    const baseRate = getOJKRate(basePrice, region, v.insuranceType);

    let totalRate = baseRate;
    if (v.expansions.authorizedWorkshop) totalRate += AUTHORIZED_WORKSHOP_RATE;

    if (v.expansions.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (v.expansions.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;
    if (v.expansions.srcc) totalRate += v.insuranceType === InsuranceType.COMPREHENSIVE ? 0.05 : 0.035;
    if (v.expansions.terrorism) totalRate += v.insuranceType === InsuranceType.COMPREHENSIVE ? 0.05 : 0.035;

    let premium = (totalRate / 100) * (basePrice * 1000000);
    premium += v.expansions.tpl * 10000; 

    let discount = 0;
    if (v.discountType === 'PERCENT') {
      const pct = Math.min(v.discountValue, 25);
      discount = (pct / 100) * premium;
    } else {
      discount = Math.min(v.discountValue, 0.25 * premium);
    }

    const finalPremium = premium - discount;
    const total = finalPremium + STAMP_DUTY + provider.adminFee;

    return { 
      basePremium: premium, 
      discount, 
      finalPremium, 
      commission: finalPremium * 0.25, 
      total, 
      coins: finalPremium * provider.extraCoins 
    };
  };

  const handlePhotoUpload = (id: keyof typeof v.photos, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setV(prev => ({ ...prev, photos: { ...prev.photos, [id]: reader.result as string } }));
    reader.readAsDataURL(file);
  };

  const runAIScore = async () => {
    setLoading(true);
    setLoadProgress(0);

    const steps = [
      { p: 15, s: 'Decrypting Documents' },
      { p: 35, s: 'Verifying Identity Match' },
      { p: 55, s: 'Scanning Exterior Surface' },
      { p: 75, s: 'Analyzing Structural Damage' },
      { p: 95, s: 'Finalizing Neural Matrix' }
    ];

    for (const step of steps) {
      await new Promise(r => setTimeout(r, 600));
      setLoadProgress(step.p);
      setLoadStatus(step.s);
    }

    const imagesToVerify = Object.entries(v.photos)
      .filter(([key, val]) => val !== null)
      .map(([key, val]) => ({ label: key, base64: val as string }));

    const res = await analyzeVehicleVerification(imagesToVerify);
    setLoading(false);

    if (res.success && res.data) {
      setV(prev => ({ ...prev, aiScoring: res.data!.overallScore }));
      setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    } else {
      setV(prev => ({ ...prev, aiScoring: 85 }));
      setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    }
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-2 text-gray-600 hover:text-primary-500 tap-feedback">
          <ChevronLeft/>
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">SurePath <span className="text-primary-500">Auto</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-1 rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 transition-all duration-700 ease-out" style={{ width: `${(step/8)*100}%` }}></div>
          </div>
        </div>
      </div>

      {loading && <NeuralLoadingIndicator progress={loadProgress} status={loadStatus} />}

      {!loading && step === CarInsuranceStep.VEHICLE_DATA && (
        <div className="space-y-6 animate-fade-in">
          <div className="space-y-4">
            <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Step 1: Data Kendaraan</p>
            <div className="grid grid-cols-2 gap-3">
              {['TOYOTA', 'HONDA', 'MITSUBISHI', 'BMW', 'WULING', 'OTHERS'].map(b => (
                <button 
                  key={b} 
                  onClick={() => setV({...v, brand: b, isOtherBrand: b === 'OTHERS'})}
                  className={`p-4 glass-card rounded-2xl border-2 transition-all font-black text-[0.65rem] uppercase tracking-widest tap-feedback ${v.brand === b ? 'border-primary-500 text-primary-500 bg-primary-500/5' : 'border-transparent dark:text-white text-gray-900'}`}
                >
                  {b}
                </button>
              ))}
            </div>

            {v.isOtherBrand ? (
              <input 
                placeholder="Masukkan Merk Mobil" 
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5 font-bold outline-none focus:border-primary-500 transition-all"
                value={v.otherBrand}
                onChange={e => setV({...v, otherBrand: e.target.value.toUpperCase()})}
              />
            ) : (
              <select 
                className="w-full p-4 glass-card rounded-xl border border-black/5 dark:border-white/5 font-bold outline-none focus:border-primary-500 transition-all"
                onChange={e => {
                  const m = CAR_DATABASE.find(c => c.code === e.target.value);
                  if (m) setV({...v, modelCode: m.code, price: m.yearPrices[v.year] || 0});
                }}
              >
                <option value="">Pilih Tipe Mobil</option>
                {CAR_DATABASE.filter(c => c.brand === v.brand).map(m => (
                  <option key={m.code} value={m.code}>{m.modelName}</option>
                ))}
              </select>
            )}

            <div className="space-y-1">
              <label className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest ml-2">Harga Kendaraan (Juta Rupiah)</label>
              <div className="flex items-center gap-2">
                 <input 
                  type="number" 
                  value={v.manualPrice || v.price || ''}
                  className="flex-1 p-4 glass-card rounded-xl border border-black/5 dark:border-white/5 font-bold outline-none transition-all"
                  onChange={e => setV({...v, manualPrice: parseFloat(e.target.value)})}
                />
                <span className="text-[0.6rem] font-black text-gray-400 uppercase">Juta</span>
              </div>
            </div>

            <div className="space-y-1">
               <label className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest ml-2">Plat Nomor (AA-BBBB-CCC)</label>
               <div className="grid grid-cols-4 gap-2">
                  <input placeholder="AA" maxLength={2} className="p-4 glass-card rounded-xl text-center font-bold uppercase transition-all" value={v.plateDetails.regionCode} onChange={e => setV({...v, plateDetails: {...v.plateDetails, regionCode: e.target.value.toUpperCase()}})} />
                  <input placeholder="8888" maxLength={4} className="col-span-2 p-4 glass-card rounded-xl text-center font-bold transition-all" value={v.plateDetails.number} onChange={e => setV({...v, plateDetails: {...v.plateDetails, number: e.target.value}})} />
                  <input placeholder="CCC" maxLength={3} className="p-4 glass-card rounded-xl text-center font-bold uppercase transition-all" value={v.plateDetails.suffix} onChange={e => setV({...v, plateDetails: {...v.plateDetails, suffix: e.target.value.toUpperCase()}})} />
               </div>
            </div>

            <div className="grid grid-cols-2 gap-3">
               <div className="space-y-1">
                  <label className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest ml-2">Penggunaan</label>
                  <select className="w-full p-4 glass-card rounded-xl font-bold transition-all" value={v.usage} onChange={e => setV({...v, usage: e.target.value as any})}>
                    <option value="PERSONAL">Pribadi</option>
                    <option value="COMMERCIAL">Komersial</option>
                    <option value="DINAS">Dinas</option>
                  </select>
               </div>
               <div className="space-y-1">
                  <label className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest ml-2">Kondisi</label>
                  <select className="w-full p-4 glass-card rounded-xl font-bold transition-all" value={v.condition} onChange={e => setV({...v, condition: e.target.value as any})}>
                    <option value="NEW">Baru</option>
                    <option value="USED">Bekas</option>
                  </select>
               </div>
            </div>
          </div>
          <button onClick={() => setStep(CarInsuranceStep.COVERAGE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl tap-feedback hover:brightness-110">Pilih Perlindungan</button>
        </div>
      )}

      {!loading && step === CarInsuranceStep.COVERAGE && (
        <div className="space-y-6 animate-fade-in">
          <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Step 2: Pilihan Coverage</p>
          <div className="grid grid-cols-2 gap-3">
            {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(t => (
              <button 
                key={t} 
                onClick={() => setV({...v, insuranceType: t})}
                className={`p-6 glass-card rounded-3xl border-2 transition-all tap-feedback ${v.insuranceType === t ? 'border-primary-500 bg-primary-500/5' : 'border-transparent'}`}
              >
                <p className="font-black dark:text-white text-gray-900 uppercase text-sm">{t}</p>
                <p className="text-[0.5rem] font-bold text-gray-500 uppercase mt-1 tracking-widest">{t === InsuranceType.COMPREHENSIVE ? 'All Risk' : 'Total Loss Only'}</p>
              </button>
            ))}
          </div>

          <div className="space-y-3">
             <h4 className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest ml-1">Perluasan Jaminan (Sesuai OJK)</h4>
             <div className="grid gap-2">
                {[
                  { id: 'flood', label: 'Banjir, Badai & Topan' },
                  { id: 'earthquake', label: 'Gempa Bumi & Tsunami' },
                  { id: 'srcc', label: 'Huru-Hara (SRCC)' },
                  { id: 'terrorism', label: 'Terorisme & Sabotase' },
                  { id: 'authorizedWorkshop', label: 'Bengkel Authorized (+0.2%)' },
                ].map(item => (
                  <label key={item.id} className="flex items-center gap-3 p-4 glass-card rounded-xl cursor-pointer hover:border-primary-500/30 transition-all tap-feedback">
                    <input 
                      type="checkbox" 
                      className="w-5 h-5 accent-primary-500 rounded transition-all" 
                      checked={(v.expansions as any)[item.id]}
                      onChange={e => setV({...v, expansions: {...v.expansions, [item.id]: e.target.checked}})} 
                    />
                    <span className="text-xs font-black uppercase dark:text-white text-gray-900">{item.label}</span>
                  </label>
                ))}
             </div>
          </div>

          <button onClick={() => setStep(CarInsuranceStep.INSURANCE_CHOICE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl tap-feedback">Bandingkan Provider</button>
        </div>
      )}

      {!loading && step === CarInsuranceStep.INSURANCE_CHOICE && (
        <div className="space-y-6 animate-fade-in">
          <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Step 3: Pilih Provider</p>
          <div className="grid gap-4">
            {INSURANCE_PROVIDERS.map((prov, i) => {
              const calc = calculatePremium(prov);
              return (
                <button 
                  key={prov.id}
                  style={{ animationDelay: `${i * 100}ms` }}
