                  className={`p-6 glass-card rounded-[2.5rem] border-2 text-left transition-all animate-fade-in tap-feedback ${v.selectedProvider?.id === prov.id ? 'border-primary-500 bg-primary-500/5' : 'border-transparent'}`}
                >
                  <div className="flex justify-between items-start mb-4">
                    <div className="flex items-center gap-4">
                      <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500">
                        <prov.logo size={28}/>
                      </div>
                      <div>
                        <p className="font-black dark:text-white text-gray-900 uppercase">{prov.name}</p>
                        <div className="flex items-center gap-1 mt-1">
                          <Star size={10} className="fill-amber-500 text-amber-500"/>
                          <span className="text-[0.55rem] font-black text-gray-400 uppercase">{prov.rating} Score</span>
