                      </div>
                    </div>
                    <div className="text-right">
                      <p className="text-[0.5rem] font-black text-gray-400 uppercase">Premi</p>
                      <p className="text-xl font-black text-primary-500">{formatIDR(calc.finalPremium)}</p>
                    </div>
                  </div>
                </button>
              );
            })}
          </div>
          <button disabled={!v.selectedProvider} onClick={() => setStep(CarInsuranceStep.SUMMARY_DOCS)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl disabled:opacity-50 transition-all tap-feedback">Lihat Summary Quo</button>
        </div>
      )}

      {step === CarInsuranceStep.UPLOAD_VEHICLE && !loading && (
        <div className="space-y-8 animate-fade-in">
          <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Step 5: Foto Survey & STNK</p>
          <div className="grid grid-cols-2 gap-4">
             {([
                ['stnk', 'STNK Kendaraan', FileText],
                ['carFront', 'Mobil Tampak Depan', Camera],
                ['carBack', 'Mobil Tampak Belakang', Camera],
                ['carLeft', 'Mobil Tampak Kiri', Camera],
                ['carRight', 'Mobil Tampak Kanan', Camera],
                ['interior', 'Interior/Dashboard', MobileIcon]
             ] as const).map(([id, label, Icon], i) => (
                <div key={id} style={{ animationDelay: `${i * 50}ms` }} className="relative aspect-square glass-card rounded-[2.5rem] border border-black/5 dark:border-white/5 flex flex-col items-center justify-center p-4 group overflow-hidden animate-fade-in tap-feedback">
