                   )}
                   <input type="file" accept="image/*" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => e.target.files && handlePhotoUpload(id, e.target.files[0])} />
                   {v.photos[id] && <div className="absolute top-3 right-3 p-1.5 bg-primary-500 text-white rounded-full shadow-lg scale-in-center"><Check size={10} strokeWidth={4}/></div>}
                </div>
             ))}
