const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(CarInsuranceStep.VEHICLE_DATA);
  const [v, setV] = useState<VehicleState>({
    brand: '', isOtherBrand: false, otherBrand: '',
    modelCode: '', isOtherModel: false, otherModel: '',
    year: 2024, price: 0, manualPrice: null,
    plateDetails: { regionCode: '', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { 
      flood: false, earthquake: false, srcc: false, terrorism: false, 
      authorizedWorkshop: false, paDriver: false, paPassenger: false, tpl: 0 
    },
    promoCode: '', discountType: 'PERCENT', discountValue: 0,
    photos: { 
      ktp: null, stnk: null, stnkFront: null, stnkBack: null, 
      carFront: null, carBack: null, carLeft: null, carRight: null, 
      dashboard: null, interior: null 
    },
    aiScoring: 0, selectedProvider: null
  });

  const [loading, setLoading] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const [loadStatus, setLoadStatus] = useState('Initializing Audit');

  const calculatePremium = (provider: Provider) => {
    const basePrice = v.manualPrice || v.price; 
    const region = getRegionFromPlate(v.plateDetails.regionCode);
    const baseRate = getOJKRate(basePrice, region, v.insuranceType);
    let premium = (baseRate / 100) * (basePrice * 1000000);
    const total = premium + STAMP_DUTY + provider.adminFee;
    return { finalPremium: premium, total, coins: premium * provider.extraCoins };
  };

  const runAIScore = async () => {
    setLoading(true);
    const steps = [
      { p: 20, s: 'Scanning Documents' },
      { p: 50, s: 'Verifying Exterior' },
      { p: 80, s: 'Analyzing AI Matrix' },
      { p: 100, s: 'Audit Complete' }
    ];
    for (const step of steps) {
      await new Promise(r => setTimeout(r, 600));
      setLoadProgress(step.p);
      setLoadStatus(step.s);
    }
    setV(prev => ({ ...prev, aiScoring: 92 }));
    setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    setLoading(false);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-2 text-gray-600 hover:text-primary-500 tap-feedback">
          <ChevronLeft/>
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">SurePath <span className="text-primary-500">Auto</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-1 rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 transition-all duration-700 ease-out" style={{ width: `${(step/8)*100}%` }}></div>
          </div>
        </div>
      </div>

      {loading ? (
        <NeuralLoadingIndicator progress={loadProgress} status={loadStatus} />
      ) : step === CarInsuranceStep.VEHICLE_DATA ? (
        <div className="space-y-6 animate-fade-in">
           <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Vehicle Details</p>
           <div className="grid grid-cols-2 gap-3">
              {['TOYOTA', 'HONDA', 'BMW', 'WULING'].map(b => (
                <button 
                  key={b} 
                  onClick={() => setV({...v, brand: b})}
                  className={`p-4 glass-card rounded-2xl border-2 transition-all font-black text-[0.65rem] uppercase tracking-widest tap-feedback ${v.brand === b ? 'border-primary-500 text-primary-500 bg-primary-500/5' : 'border-transparent dark:text-white text-gray-900'}`}
                >
                  {b}
                </button>
              ))}
           </div>
           <input placeholder="License Plate (e.g. B 1234 XYZ)" className="w-full p-4 glass-card rounded-xl font-bold uppercase transition-all" value={v.plateDetails.number} onChange={e => setV({...v, plateDetails: {...v.plateDetails, number: e.target.value.toUpperCase()}})} />
           <button onClick={() => setStep(CarInsuranceStep.INSURANCE_CHOICE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl tap-feedback hover:brightness-110">Compare Providers</button>
        </div>
      ) : (
        <div className="text-center py-20 text-gray-400 font-bold uppercase text-xs tracking-widest">
           Detailed Flow in Progress...
        </div>
      )}
    </div>
  );
};

