const ClaimScreen = ({ onBack }: { onBack: () => void }) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const res = await analyzeClaimPhoto(reader.result as string);
        if (res.success && res.data) setResult(res.data);
        setLoading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="p-6 max-w-lg mx-auto animate-fade-in pb-32">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="p-2 text-gray-600 hover:text-primary-500 tap-feedback"><ChevronLeft/></button>
        <h2 className="text-2xl font-black uppercase tracking-tighter">Neural <span className="text-primary-500">Claim</span></h2>
      </div>
      {!result ? (
        <div className="aspect-square glass-card rounded-[3rem] border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center p-12 text-center relative overflow-hidden group tap-feedback">
          {loading ? (
             <div className="flex flex-col items-center gap-6">
                <Loader2 size={48} className="animate-spin text-primary-500" />
                <p className="text-[0.6rem] text-primary-500 font-black uppercase tracking-[0.2em]">Analyzing Severity...</p>
             </div>
          ) : (
            <>
              <Camera size={48} className="text-primary-500 mb-4 group-hover:scale-110 transition-transform" />
              <p className="font-black uppercase text-gray-900 dark:text-white">Foto Kerusakan</p>
              <p className="text-[0.6rem] text-gray-400 mt-2 uppercase">AI will calculate repair costs automatically</p>
            </>
          )}
          <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer disabled:cursor-not-allowed" disabled={loading} />
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in text-center">
          <div className="bg-primary-500 p-8 rounded-[3rem] text-white shadow-xl animate-pop-in">
            <p className="text-xs uppercase font-bold opacity-80">Repair Estimate</p>
            <h3 className="text-3xl font-black">{formatIDR(result.totalEstimasi)}</h3>
            <p className="mt-2 text-sm opacity-90">{result.aiInsight}</p>
          </div>
          <button onClick={() => setResult(null)} className="w-full py-5 glass-card rounded-2xl font-black uppercase text-[0.7rem] dark:text-white text-gray-900 border border-black/5 tap-feedback">New Analysis</button>
        </div>
      )}

      {loading && <div className="mt-12"><ClaimSkeleton /></div>}
    </div>
  );
};

