  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const res = await analyzeClaimPhoto(reader.result as string);
        if (res.success && res.data) setResult(res.data);
        setLoading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'Ringan': return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      case 'Sedang': return 'text-amber-500 bg-amber-500/10 border-amber-500/20';
      case 'Berat': return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case 'Total Loss': return 'text-red-500 bg-red-500/10 border-red-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
