    const steps = [
      { p: 15, s: 'Authenticating Documents...' },
      { p: 30, s: 'Verifying Security Holograms...' },
      { p: 45, s: 'Neural Panel Surface Scan...' },
      { p: 60, s: 'Identifying Micro-Defects...' },
      { p: 80, s: 'Calculating Risk Probability...' },
      { p: 95, s: 'Cross-referencing Global Data...' },
      { p: 100, s: 'Neural Audit Finalized' }
    ];
    for (const s of steps) {
      await new Promise(r => setTimeout(r, 700));
      setLoadProgress(s.p);
      setLoadStatus(s.s);
    }
    setV(prev => ({ ...prev, aiScoring: 94 }));
    setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    setLoading(false);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
