const CarWizard = ({ onBack }: { onBack: () => void }) => {
  const [step, setStep] = useState(CarInsuranceStep.VEHICLE_DATA);
  const [v, setV] = useState<VehicleState>({
    brand: '', isOtherBrand: false, otherBrand: '',
    modelCode: '', isOtherModel: false, otherModel: '',
    year: 2024, price: 0, manualPrice: null,
    plateDetails: { regionCode: '', number: '', suffix: '' },
    usage: 'PERSONAL', condition: 'NEW',
    insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { 
      flood: false, earthquake: false, srcc: false, terrorism: false, 
      authorizedWorkshop: false, paDriver: false, paPassenger: false, tpl: 0 
    },
    promoCode: '', discountType: 'PERCENT', discountValue: 0,
    photos: { 
      ktp: null, stnk: null, stnkFront: null, stnkBack: null, 
      carFront: null, carBack: null, carLeft: null, carRight: null, 
      dashboard: null, interior: null 
    },
    aiScoring: 0, selectedProvider: null
  });

  const [loading, setLoading] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const [loadStatus, setLoadStatus] = useState('Initializing Audit');
  const [activeGuide, setActiveGuide] = useState<string | null>(null);

  const handlePhotoUpload = (id: keyof typeof v.photos, file: File) => {
    const reader = new FileReader();
    reader.onloadend = () => setV(prev => ({ ...prev, photos: { ...prev.photos, [id]: reader.result as string } }));
    reader.readAsDataURL(file);
  };

  const runAIScore = async () => {
    setLoading(true);
    const steps = [
      { p: 10, s: 'Authenticating Identity Documents...' },
      { p: 25, s: 'Verifying Security Holograms...' },
      { p: 40, s: 'Neural Panel Surface Integrity Scan...' },
      { p: 55, s: 'Identifying Micro-Defects & Anomalies...' },
      { p: 70, s: 'Cross-referencing Global Risk Data...' },
      { p: 85, s: 'Calculating Dynamic Premium Matrix...' },
      { p: 100, s: 'Neural Audit Finalized' }
    ];
    for (const s of steps) {
      await new Promise(r => setTimeout(r, 700));
      setLoadProgress(s.p);
      setLoadStatus(s.s);
    }
    setV(prev => ({ ...prev, aiScoring: 94 }));
    setStep(CarInsuranceStep.FINAL_CONFIRMATION);
    setLoading(false);
  };

  return (
    <div className="p-6 max-w-lg mx-auto pb-32 animate-fade-in">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={() => step > 1 ? setStep(step - 1) : onBack()} className="p-2 text-gray-600 hover:text-primary-500 tap-feedback">
          <ChevronLeft/>
        </button>
        <div className="flex-1">
          <h2 className="text-xl font-black uppercase text-gray-900 dark:text-white tracking-tighter">SurePath <span className="text-primary-500">Auto</span></h2>
          <div className="h-1 bg-black/5 dark:bg-white/5 mt-1 rounded-full overflow-hidden">
            <div className="h-full bg-primary-500 transition-all duration-700 ease-out" style={{ width: `${(step/8)*100}%` }}></div>
          </div>
        </div>
      </div>

      {activeGuide && <PhotoGuideModal type={activeGuide} onClose={() => setActiveGuide(null)} />}

      {loading ? (
        <NeuralLoadingIndicator progress={loadProgress} status={loadStatus} />
      ) : step === CarInsuranceStep.VEHICLE_DATA ? (
        <div className="space-y-6 animate-fade-in">
           <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em] ml-1">Vehicle Details</p>
           <div className="grid grid-cols-2 gap-3">
              {['TOYOTA', 'HONDA', 'BMW', 'WULING'].map(b => (
                <button 
                  key={b} 
                  onClick={() => setV({...v, brand: b})}
                  className={`p-4 glass-card rounded-2xl border-2 transition-all font-black text-[0.65rem] uppercase tracking-widest tap-feedback ${v.brand === b ? 'border-primary-500 text-primary-500 bg-primary-500/5' : 'border-transparent dark:text-white text-gray-900'}`}
                >
                  {b}
                </button>
              ))}
           </div>
           <input placeholder="License Plate (e.g. B 1234 XYZ)" className="w-full p-4 glass-card rounded-xl font-bold uppercase transition-all" value={v.plateDetails.number} onChange={e => setV({...v, plateDetails: {...v.plateDetails, number: e.target.value.toUpperCase()}})} />
           <button onClick={() => setStep(CarInsuranceStep.INSURANCE_CHOICE)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase text-sm shadow-xl tap-feedback">Compare Providers</button>
        </div>
      ) : step === CarInsuranceStep.UPLOAD_VEHICLE ? (
        <div className="space-y-8 animate-fade-in">
          <div className="flex items-center justify-between px-1">
            <p className="text-[0.6rem] font-black text-gray-500 uppercase tracking-[0.2em]">Visual Survey</p>
            <button onClick={() => setActiveGuide('stnk')} className="flex items-center gap-1.5 text-[0.55rem] font-black uppercase text-primary-500 hover:opacity-80 transition-opacity">
              <Info size={14} /> Global Guide
            </button>
          </div>

          <div className="grid grid-cols-2 gap-4">
             {([
                ['stnkFront', 'STNK Front', FileText],
                ['stnkBack', 'STNK Back', FileText],
                ['carFront', 'Car Front (3/4)', Camera],
                ['carBack', 'Car Back (3/4)', Camera],
                ['carLeft', 'Left Profile', Camera],
                ['carRight', 'Right Profile', Camera],
                ['dashboard', 'Dashboard & KM', MobileIcon]
             ] as const).map(([id, label, Icon], i) => (
                <div key={id} style={{ animationDelay: `${i * 50}ms` }} className="relative aspect-square glass-card rounded-[2.5rem] border border-black/5 dark:border-white/5 flex flex-col items-center justify-center p-4 group overflow-hidden animate-fade-in tap-feedback">
                   {v.photos[id] ? (
                      <div className="absolute inset-0 w-full h-full">
                        <img src={v.photos[id]!} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt={label} />
                        <button 
                          onClick={(e) => { e.preventDefault(); setV(prev => ({ ...prev, photos: { ...prev.photos, [id]: null } })); }}
                          className="absolute top-3 right-3 p-1.5 bg-black/50 text-white rounded-full backdrop-blur-md opacity-0 group-hover:opacity-100 transition-opacity z-10"
                        >
                          <X size={14} />
                        </button>
                      </div>
                   ) : (
                      <>
                        <div className="w-12 h-12 bg-gray-50 dark:bg-white/5 rounded-2xl flex items-center justify-center text-gray-300 mb-3 group-hover:scale-110 transition-transform">
                          <Icon size={24} />
                        </div>
                        <span className="text-[0.55rem] font-black uppercase text-gray-400 tracking-widest text-center px-2">{label}</span>
                        <button 
                          onClick={() => setActiveGuide(id)}
                          className="mt-3 p-1.5 bg-primary-500/10 text-primary-500 rounded-full hover:bg-primary-500/20 transition-colors"
                        >
                          <Eye size={12} strokeWidth={3}/>
                        </button>
                        <input 
                          type="file" 
                          accept="image/*" 
                          className="absolute inset-0 opacity-0 cursor-pointer" 
                          onChange={e => e.target.files && handlePhotoUpload(id as any, e.target.files[0])} 
                        />
                      </>
                   )}
                   {v.photos[id] && (
                    <div className="absolute bottom-3 left-3 px-2 py-1 bg-primary-500 text-white rounded-lg text-[0.5rem] font-black uppercase tracking-widest shadow-lg flex items-center gap-1">
                      <Check size={8} strokeWidth={4}/> Done
                    </div>
                   )}
                </div>
             ))}
          </div>

          <div className="p-6 bg-amber-500/10 border border-amber-500/20 rounded-[2rem] space-y-2">
            <div className="flex items-center gap-2 text-amber-600">
              <AlertTriangle size={18} />
              <p className="text-[0.65rem] font-black uppercase tracking-widest">Audit Requirement</p>
            </div>
            <p className="text-[0.6rem] text-amber-700/80 font-medium leading-relaxed">
              Our Neural Audit Engine requires clear, unedited photos. Photos with high glare or blur will result in policy rejection.
            </p>
          </div>

          <button 
            disabled={Object.values(v.photos).filter(p => p !== null).length < 7}
            onClick={runAIScore}
            className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase text-sm shadow-2xl flex items-center justify-center gap-3 disabled:opacity-50 transition-all tap-feedback"
          >
            <Sparkles size={20} className="animate-pulse" />
            Launch Neural Audit
          </button>
        </div>
      ) : (
        <div className="text-center py-20 text-gray-400 font-bold uppercase text-xs tracking-widest">
           Detailed flow for step {step} is coming soon.
        </div>
      )}
    </div>
  );
};

