const ClaimScreen = ({ onBack }: { onBack: () => void }) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ClaimAnalysisData | null>(null);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      setLoading(true);
      const reader = new FileReader();
      reader.onloadend = async () => {
        const res = await analyzeClaimPhoto(reader.result as string);
        if (res.success && res.data) setResult(res.data);
        setLoading(false);
      };
      reader.readAsDataURL(file);
    }
  };

  const getSeverityColor = (severity: string) => {
    switch (severity) {
      case 'Ringan': return 'text-blue-500 bg-blue-500/10 border-blue-500/20';
      case 'Sedang': return 'text-amber-500 bg-amber-500/10 border-amber-500/20';
      case 'Berat': return 'text-orange-500 bg-orange-500/10 border-orange-500/20';
      case 'Total Loss': return 'text-red-500 bg-red-500/10 border-red-500/20';
      default: return 'text-gray-500 bg-gray-500/10 border-gray-500/20';
    }
  };

  return (
    <div className="p-6 max-w-lg mx-auto animate-fade-in pb-32">
      <div className="flex items-center gap-4 mb-8">
        <button onClick={onBack} className="p-2 text-gray-600 hover:text-primary-500 tap-feedback"><ChevronLeft/></button>
        <h2 className="text-2xl font-black uppercase tracking-tighter">Neural <span className="text-primary-500">Claim</span></h2>
      </div>

      {!result ? (
        <div className="aspect-square glass-card rounded-[3rem] border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center p-12 text-center relative overflow-hidden group tap-feedback shadow-lg">
          {loading ? (
             <>
                <PhotoScannerEffect />
                <div className="flex flex-col items-center gap-8 relative z-30">
                  <div className="w-24 h-24 bg-primary-500/20 rounded-full flex items-center justify-center shadow-[0_0_40px_rgba(16,185,129,0.2)]">
                    <Loader2 size={48} className="animate-spin text-primary-500" />
                  </div>
                  <div className="space-y-2">
                    <p className="text-sm font-black text-primary-500 uppercase tracking-[0.2em]">Neural Auditing Damage...</p>
                    <p className="text-[0.6rem] text-gray-400 font-bold uppercase tracking-widest animate-pulse">Calculating Pixel Density & Geometry</p>
                  </div>
                </div>
             </>
          ) : (
            <>
              <Camera size={48} className="text-primary-500 mb-4 group-hover:scale-110 transition-transform" />
              <p className="font-black uppercase text-gray-900 dark:text-white">Upload Damage Photo</p>
              <p className="text-[0.6rem] text-gray-400 mt-2 uppercase tracking-widest">AI Audit will estimate costs in seconds</p>
