          )}
          <input type="file" accept="image/*" onChange={handleUpload} className="absolute inset-0 opacity-0 cursor-pointer disabled:cursor-not-allowed" disabled={loading} />
        </div>
      ) : (
        <div className="space-y-6 animate-fade-in">
          <div className="relative overflow-hidden bg-primary-500 p-8 rounded-[3rem] text-white shadow-2xl animate-pop-in">
            <div className="absolute top-0 right-0 p-4 opacity-20"><Zap size={120} /></div>
            <div className="relative z-10">
              <div className="flex justify-between items-start mb-4">
                <div>
                  <p className="text-[0.6rem] uppercase font-black tracking-widest opacity-80 mb-1">AI Repair Estimate</p>
