            <div className="grid gap-3">
              {result.rincianPart.map((part, idx) => (
                <div key={idx} className="p-4 glass-card rounded-2xl border border-black/5 dark:border-white/5 flex items-center justify-between group hover:border-primary-500/30 transition-all">
