const Header = ({ darkMode, setDarkMode, onProfile, onExit }: { darkMode: boolean, setDarkMode: (d: boolean) => void, onProfile: () => void, onExit: () => void }) => {
  const handleShare = async () => {
    const shareData = {
      title: 'SurePath Insurtech',
      text: 'Explore neural insurance protection at SurePath.',
      url: window.location.href,
    };
    if (navigator.share) {
      try {
        await navigator.share(shareData);
      } catch (err) {
        console.log('Share failed', err);
      }
    } else {
      navigator.clipboard.writeText(window.location.href);
      alert('Link copied to clipboard!');
    }
  };

  return (
    <header className="sticky top-0 z-40 h-20 glass-card px-6 flex items-center justify-between border-b border-black/5 dark:border-white/5">
      <div className="flex items-center gap-3 group cursor-pointer" onClick={() => onExit()}>
        <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white shadow-lg group-hover:rotate-12 transition-transform duration-500">
          <ShieldCheck size={24}/>
        </div>
        <span className="font-black text-xl tracking-tighter uppercase dark:text-white text-gray-900">Sure<span className="text-primary-500">Path</span></span>
      </div>
      <div className="flex items-center gap-3">
        <button 
          onClick={handleShare}
          className="p-2.5 bg-gray-100 dark:bg-white/5 rounded-xl text-gray-400 hover:text-primary-500 transition-colors"
        >
          <Share2 size={18}/>
        </button>
        <div className="flex items-center bg-gray-100 dark:bg-white/5 p-1 rounded-2xl border border-black/5 dark:border-white/10">
          <button 
            onClick={() => { setDarkMode(false); document.body.classList.remove('dark'); }}
            className={`p-2 rounded-xl transition-all ${!darkMode ? 'bg-white text-primary-500 shadow-sm' : 'text-gray-400'}`}
          >
            <Sun size={18}/>
          </button>
          <button 
            onClick={() => { setDarkMode(true); document.body.classList.add('dark'); }}
            className={`p-2 rounded-xl transition-all ${darkMode ? 'bg-gray-800 text-primary-500 shadow-sm' : 'text-gray-400'}`}
