const App = () => {
  const [currentPage, setPage] = useState('home');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [forcedPortal, setForcedPortal] = useState(false);

  // Initialize theme based on local time
  const [darkMode, setDarkMode] = useState(() => {
    const hours = new Date().getHours();
    return hours >= 18 || hours < 6;
  });

  useEffect(() => {
    const checkTheme = () => {
      const hours = new Date().getHours();
      const isNight = hours >= 18 || hours < 6;
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      const shouldBeDark = isNight || prefersDark;

      setDarkMode(shouldBeDark);
      if (shouldBeDark) {
        document.body.classList.add('dark');
      } else {
        document.body.classList.remove('dark');
      }
    };

    checkTheme();
    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
    const handler = () => checkTheme();
    mediaQuery.addEventListener('change', handler);
    const themeInterval = setInterval(checkTheme, 60000);
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      mediaQuery.removeEventListener('change', handler);
      clearInterval(themeInterval);
    };
  }, []);

  if (!isMobile && !forcedPortal) {
    return <DesktopWebsite onEnterPortal={() => setForcedPortal(true)} />;
  }

  return (
    <MobileApp 
      currentPage={currentPage} 
      setPage={setPage} 
      darkMode={darkMode} 
      setDarkMode={setDarkMode}
      onExit={() => setForcedPortal(false)} 
    />
  );
};

export default App;

