  if (!isOpen) return null;

  const loginSteps = [
    "Establishing Uplink...",
    "Querying Neural Core...",
    "Verifying Credentials...",
    "Syncing Profile Matrix...",
    "Access Granted."
  ];

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      onLogin(role);
