  const handleShare = async () => {
    const shareData = {
      title: 'SurePath Insurtech',
      text: 'Explore neural insurance protection at SurePath.',
      url: window.location.href,
    };
    if (navigator.share) {
      try {
        await navigator.share(shareData);
