const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

// --- AUTH GATEWAY COMPONENTS ---

const AuthGateway = ({ onLogin, darkMode }: { onLogin: (role: string, email: string) => void, darkMode: boolean }) => {
  const [view, setView] = useState<'login' | 'reset'>('login');
  const [role, setRole] = useState<'Member' | 'Partner' | 'Admin'>('Member');
  const [email, setEmail] = useState(localStorage.getItem('rememberedEmail') || '');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(!!localStorage.getItem('rememberedEmail'));
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loginSteps = [
    "Establishing Uplink...",
    "Querying Neural Core...",
    "Verifying Credentials...",
    "Syncing Profile Matrix...",
    "Access Granted."
  ];

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    // Simple validation simulation
    if (password.length < 4) {
      setError("Insecure Access Key. Minimum 4 characters required.");
      return;
    }

    setLoading(true);

    // Simulate API network latency
    setTimeout(() => {
      if (rememberMe) {
        localStorage.setItem('rememberedEmail', email);
      } else {
        localStorage.removeItem('rememberedEmail');
      }
      setLoading(false);
      onLogin(role, email);
    }, 4000);
  };

  const handleReset = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setTimeout(() => {
      setLoading(false);
      alert('Security recovery payload broadcasted to ' + email);
      setView('login');
    }, 3000);
  };

  return (
    <div className={`fixed inset-0 z-[200] flex flex-col items-center justify-center p-6 ${darkMode ? 'bg-dark-bg' : 'bg-slate-50'}`}>
      <div className="absolute inset-0 neural-grid opacity-20"></div>
      <div className="absolute top-[-10%] right-[-10%] w-[50%] h-[50%] bg-primary-500/10 rounded-full blur-[120px] animate-pulse-slow"></div>
      <div className="absolute bottom-[-10%] left-[-10%] w-[50%] h-[50%] bg-blue-500/10 rounded-full blur-[120px] animate-pulse-slow animation-delay-2000"></div>

      <div className="relative w-full max-w-md glass-card rounded-[3.5rem] p-8 md:p-12 shadow-2xl border border-white/20 animate-pop-in overflow-hidden min-h-[600px] flex flex-col justify-center">
        {loading ? (
          <InformativeNeuralLoader messages={view === 'login' ? loginSteps : ["Generating Recovery Key...", "Encrypting Data...", "Payload Ready."]} />
        ) : (
          <div className="relative z-10 space-y-8">
            <div className="flex flex-col items-center text-center gap-4">
              <div className="w-16 h-16 bg-primary-500 rounded-3xl flex items-center justify-center text-white shadow-2xl rotate-3 animate-float">
                <ShieldCheck size={36}/>
              </div>
              <div>
                <h1 className="font-black text-3xl tracking-tighter uppercase dark:text-white text-gray-900">Sure<span className="text-primary-500">Path</span></h1>
                <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-[0.4em] mt-1">Neural Protection Hub</p>
              </div>
            </div>

            {view === 'login' ? (
              <div className="animate-fade-in space-y-6">
                <div className="text-center">
                  <h2 className="text-2xl font-black uppercase tracking-tighter dark:text-white text-gray-900">Portal <span className="text-primary-500">Access</span></h2>
                </div>

                <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-[1.8rem] border border-black/5 dark:border-white/10">
                  {(['Member', 'Partner', 'Admin'] as const).map(r => (
                    <button 
                      key={r}
                      onClick={() => setRole(r)}
                      className={`flex-1 py-3 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest transition-all ${role === r ? 'bg-white dark:bg-gray-800 text-primary-500 shadow-xl scale-105' : 'text-gray-400'}`}
                    >
                      {r}
                    </button>
                  ))}
                </div>

                {error && (
                  <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3 text-rose-500 animate-bounce-subtle">
                    <AlertTriangle size={18}/>
                    <p className="text-[0.65rem] font-bold uppercase">{error}</p>
                  </div>
                )}

                <form onSubmit={handleLoginSubmit} className="space-y-4">
                  <div className="relative group">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18}/>
                    <input 
                      type="email" 
                      required
