                      className="w-full pl-14 pr-4 py-5 bg-slate-100/50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-2xl font-bold text-sm focus:ring-2 focus:ring-primary-500 focus:bg-white dark:focus:bg-white/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600 text-slate-700 dark:text-slate-200 shadow-sm"
                      value={email}
                      onChange={(e) => setEmail(e.target.value)}
                    />
                  </div>
                  <div className="relative group">
                    <Lock className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18}/>
                    <input 
                      type="password" 
                      required
                      placeholder="ACCESS KEY"
                      className="w-full pl-14 pr-4 py-5 bg-slate-100/50 dark:bg-white/5 border border-slate-200 dark:border-white/10 rounded-2xl font-bold text-sm focus:ring-2 focus:ring-primary-500 focus:bg-white dark:focus:bg-white/10 outline-none transition-all placeholder:text-slate-400 dark:placeholder:text-slate-600 text-slate-700 dark:text-slate-200 shadow-sm"
                      value={password}
