                  <button 
                    className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-[0.75rem] tracking-[0.2em] shadow-2xl shadow-primary-500/40 hover:scale-[1.02] active:scale-95 transition-all flex items-center justify-center gap-3 mt-4"
