                  </button>
                </form>
              </div>
            ) : (
              <div className="animate-fade-in space-y-8">
                <button onClick={() => setView('login')} className="flex items-center gap-2 text-slate-400 hover:text-primary-500 transition-colors group">
                  <ArrowLeft size={16} className="group-hover:-translate-x-1 transition-transform"/>
                  <span className="text-[0.65rem] font-black uppercase tracking-widest">Return to Base</span>
                </button>

                <div className="text-center space-y-2">
                  <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white text-gray-900">Neural <span className="text-primary-500">Recovery</span></h2>
                  <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-widest">Protocol: Identity Resync</p>
                </div>

                <form onSubmit={handleReset} className="space-y-6">
                  <div className="relative group">
                    <Mail className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-primary-500 transition-colors" size={18}/>
                    <input 
                      type="email" 
                      required
                      placeholder="REGISTERED IDENTIFIER"
