  );
};

// --- INFORMATIONAL LOADER COMPONENT ---

const InformativeNeuralLoader = ({ messages }: { messages: string[] }) => {
  const [msgIndex, setMsgIndex] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setMsgIndex((prev) => (prev + 1) % messages.length);
    }, 1200);
    return () => clearInterval(timer);
  }, [messages]);

  return (
    <div className="flex flex-col items-center justify-center space-y-8 py-10">
      <div className="relative">
        <div className="absolute inset-0 bg-primary-500/20 rounded-full blur-2xl animate-neural-pulse"></div>
        <div className="relative w-24 h-24 rounded-3xl bg-gray-900 dark:bg-white flex items-center justify-center shadow-2xl border border-white/10 overflow-hidden">
          <BrainCircuit size={48} className="text-primary-500 animate-pulse-slow relative z-10" />
          <div className="absolute inset-0 neural-grid opacity-30 animate-spin-slow"></div>
          {/* Scanning Beam */}
          <div className="absolute inset-x-0 scanning-beam animate-scan-fast"></div>
        </div>
      </div>

      <div className="text-center space-y-2 max-w-[240px]">
        <div className="h-6 overflow-hidden">
          <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.3em] animate-fade-in" key={msgIndex}>
            {messages[msgIndex]}
          </p>
        </div>
        <div className="flex justify-center gap-1.5">
          {messages.map((_, i) => (
            <div 
              key={i} 
              className={`h-1 rounded-full transition-all duration-500 ${i === msgIndex ? 'w-6 bg-primary-500' : 'w-1.5 bg-gray-200 dark:bg-white/10'}`} 
            />
          ))}
        </div>
      </div>
    </div>
  );
};

