  const [claimError, setClaimError] = useState<string | null>(null);
  const [isTerminating, setIsTerminating] = useState(false);

  const [userProfile, setUserProfile] = useState<UserState>({
    name: user.role === 'Admin' ? 'Neural Overlord' : (user.role === 'Partner' ? 'Authorized Node' : 'Ahmad Sholihin'),
    email: user.email,
    phone: '081234567890',
    ktpNo: '3171234567890001'
  });

  const [isEditing, setIsEditing] = useState(false);
  const [editForm, setEditForm] = useState(userProfile);

  const claimSteps = [
    "Analyzing Damage Burst...",
    "Scanning Chassis Geometry...",
    "Querying Repair Database...",
    "Auditing Policy Compliance...",
    "Neural Estimate Confirmed."
  ];

  const handleTermination = () => {
    setIsTerminating(true);
    setTimeout(() => {
      onLogout();
    }, 2500);
  };

  const handleSaveProfile = () => {
    setUserProfile(editForm);
    setIsEditing(false);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsAnalyzingClaim(true);
    setClaimError(null);
    setClaimResult(null);

    try {
      const reader = new FileReader();
      reader.readAsDataURL(file);
      reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await analyzeClaimPhoto(base64);

        if (response.success && response.data) {
          setClaimResult(response.data);
        } else {
          setClaimError(response.error || "Gagal menganalisa klaim.");
        }
        setIsAnalyzingClaim(false);
      };
    } catch (err) {
      setClaimError("Terjadi kesalahan teknis saat mengunggah foto.");
      setIsAnalyzingClaim(false);
    }
  };

  const handleResetClaim = () => {
    setClaimResult(null);
    setClaimError(null);
    setIsAnalyzingClaim(false);
