                                <div>
                                    <p className="text-emerald-500 mb-2">Kelebihan:</p>
                                    <ul className="space-y-1 text-gray-500">
                                        {p.advantages.map((a, i) => <li key={i} className="flex items-start gap-1">• {a}</li>)}
                                    </ul>
                                </div>
                                <div>
                                    <p className="text-rose-500 mb-2">Kekurangan:</p>
                                    <ul className="space-y-1 text-gray-500">
                                        {p.disadvantages.map((d, i) => <li key={i} className="flex items-start gap-1">• {d}</li>)}
                                    </ul>
                                </div>
                            </div>

                            <div className="flex items-center justify-between bg-primary-500/10 p-4 rounded-2xl">
                                <div>
                                    <p className="text-[0.55rem] font-black text-primary-600 uppercase">Extra Path Coins</p>
                                    <p className="text-sm font-black text-primary-600">+{p.extraCoinsPercent}% Reward</p>
                                </div>
                                <button 
                                    onClick={() => handleProviderSelect(p)}
                                    className="px-6 py-2 bg-primary-500 text-white rounded-xl text-[0.6rem] font-black uppercase"
                                >
                                    Pilih
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );

      case CarInsuranceStep.PRELIMINARY_SUMMARY:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-32">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Summary <span className="text-primary-500">Draft</span></h2>
                <div className="p-8 glass-card rounded-[3.5rem] border-2 border-primary-500/20 space-y-6">
                    <div className="space-y-2 border-b pb-4">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Detail Kendaraan</p>
                        <h4 className="text-xl font-black uppercase">{vehicle.brand} {vehicle.model}</h4>
                        <p className="text-sm font-bold text-gray-500">{vehicle.plate} • {vehicle.year} • {vehicle.usage}</p>
                    </div>
                    <div className="space-y-2 border-b pb-4">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Rincian Biaya</p>
                        <div className="flex justify-between text-sm"><span>Asuransi:</span> <span className="font-bold">{vehicle.selectedProvider?.name}</span></div>
                        <div className="flex justify-between text-sm"><span>Biaya Admin:</span> <span className="font-bold">{formatIDR(vehicle.selectedProvider?.adminFee || 0)}</span></div>
                        <div className="flex justify-between text-sm"><span>Materai:</span> <span className="font-bold">{formatIDR(STAMP_DUTY)}</span></div>
                    </div>
                    <div className="pt-2">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest mb-1">Total Premi</p>
                        <p className="text-4xl font-black text-primary-500 tracking-tighter">{formatIDR(calculateTotalPremium(vehicle, vehicle.selectedProvider))}</p>
                    </div>
                </div>

                <div className="grid gap-4">
                    <button onClick={handlePrint} className="w-full py-5 bg-gray-900 text-white rounded-3xl font-black uppercase tracking-widest flex items-center justify-center gap-3">
                        <Printer size={20}/> Simpan Sebagai PDF
                    </button>
                    <button onClick={() => setStep(CarInsuranceStep.KYC_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">
                        Lanjut Upload Data
                    </button>
                </div>
            </div>
        );

      case CarInsuranceStep.KYC_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Data <span className="text-primary-500">Nasabah</span></h2>
                <div className="aspect-video relative rounded-[2rem] overflow-hidden bg-gray-100 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer">
                    {user.ktpPhoto ? (
                        <img src={user.ktpPhoto} className="w-full h-full object-cover" />
                    ) : (
                        <>
                            <Camera size={48} className="text-gray-400 group-hover:text-primary-500 transition-colors"/>
                            <p className="text-[0.65rem] font-black uppercase text-gray-400 mt-2">Upload Foto KTP</p>
                        </>
                    )}
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('ktp', e)} />
                </div>

                {loading ? <InformativeNeuralLoader messages={["Analyzing KTP Document...", "Extracting Bio-data..."]} /> : (
                    <div className="space-y-4">
                        <input placeholder="Nama Sesuai KTP" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.name} onChange={e => setUser({...user, name: e.target.value})} />
                        <input placeholder="No. KTP" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.ktpNo} onChange={e => setUser({...user, ktpNo: e.target.value})} />
                        <input placeholder="Email" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.email} onChange={e => setUser({...user, email: e.target.value})} />
                        <input placeholder="Nomor Handphone" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.phone} onChange={e => setUser({...user, phone: e.target.value})} />
                        <button onClick={() => setStep(CarInsuranceStep.VEHICLE_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest mt-6">Lanjut</button>
                    </div>
                )}
            </div>
        );

      case CarInsuranceStep.VEHICLE_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Survei <span className="text-primary-500">Kendaraan</span></h2>

                <div className="space-y-6">
                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Dokumen</p>
                        <div className="aspect-video relative rounded-2xl bg-gray-100 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center">
                            {vehicle.photos.stnk ? <img src={vehicle.photos.stnk} className="w-full h-full object-cover rounded-2xl" /> : <><ImageIcon size={32} className="text-gray-300"/><span className="text-[0.6rem] font-bold text-gray-400 mt-2">FOTO STNK</span></>}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('stnk', e)} />
                        </div>
                    </div>

                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Kondisi Mobil</p>
                        <div className="grid grid-cols-2 gap-4">
                            {[
                                { id: 'carFront', label: 'Tampak Depan' },
                                { id: 'carBack', label: 'Tampak Belakang' },
                                { id: 'carLeft', label: 'Sisi Kiri' },
                                { id: 'carRight', label: 'Sisi Kanan' },
                                { id: 'interior', label: 'Interior' }
                            ].map(item => (
                                <div key={item.id} className="aspect-square relative rounded-2xl bg-gray-100 border border-gray-200 flex flex-col items-center justify-center overflow-hidden">
                                    {(vehicle.photos as any)[item.id] ? <img src={(vehicle.photos as any)[item.id]} className="w-full h-full object-cover" /> : <><Camera size={20} className="text-gray-300"/><span className="text-[0.5rem] font-bold text-gray-400 mt-1">{item.label}</span></>}
                                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload(item.id as any, e)} />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <button 
                    disabled={!Object.values(vehicle.photos).every(v => v !== null)}
                    onClick={() => { runVerification(); setStep(CarInsuranceStep.SURVEY_VERIFICATION); }}
                    className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest disabled:opacity-50"
                >
                    Klik Verifikasi AI
                </button>
            </div>
        );

      case CarInsuranceStep.SURVEY_VERIFICATION:
        return (
            <div className="p-6 space-y-10 animate-fade-in text-center">
                {verifying ? <InformativeNeuralLoader messages={["Checking Damage...", "Analyzing Photo Clarity...", "Verifying Policy Consistency..."]} /> : (
                    <div className="space-y-8">
                        <div className="w-32 h-32 mx-auto relative">
                            <svg className="w-full h-full" viewBox="0 0 100 100">
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#eee" strokeWidth="10" />
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#10b981" strokeWidth="10" strokeDasharray={`${vehicle.aiVerificationScore || 0} ${100 - (vehicle.aiVerificationScore || 0)}`} strokeDashoffset="25" />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-3xl font-black text-primary-500">{vehicle.aiVerificationScore}</span>
                                <span className="text-[0.5rem] font-bold text-gray-400">SCORE</span>
                            </div>
                        </div>

                        { (vehicle.aiVerificationScore || 0) >= 80 ? (
                            <div className="space-y-6">
                                <h3 className="text-2xl font-black uppercase text-emerald-500">Verified Successfully</h3>
                                <p className="text-sm text-gray-500 px-6">Kendaraan dalam kondisi layak asuransi. Data STNK sesuai dengan input fisik.</p>
                                <button onClick={() => setStep(CarInsuranceStep.FINAL_CONFIRMATION)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">Lanjutkan</button>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                <div className="p-6 bg-rose-500/10 rounded-[2rem] border border-rose-500/20 flex items-center gap-4 text-left">
                                    <ShieldAlert className="text-rose-500" size={32}/>
                                    <div>
                                        <p className="text-sm font-black text-rose-500 uppercase">Verifikasi Gagal</p>
