  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white pb-32">
        <header className="h-20 glass-card px-6 flex items-center justify-between border-b border-black/5">
            <button onClick={onExit} className="w-10 h-10 bg-gray-100 dark:bg-white/5 rounded-xl flex items-center justify-center text-gray-500"><ChevronLeft size={24}/></button>
            <div className="flex items-center gap-2"><div className="w-8 h-8 bg-primary-500 rounded-lg flex items-center justify-center text-white"><Car size={18}/></div><span className="font-black text-sm uppercase tracking-widest">Car Insurance</span></div>
            <div className="w-10"></div>
        </header>
        <main className="max-w-lg mx-auto">{renderStepContent()}</main>
