  );
};

// --- MAIN APP ---

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState<{ role: string, email: string } | null>(null);
  const [forcedPortal, setForcedPortal] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [darkMode, setDarkMode] = useState(() => {
    const h = new Date().getHours();
    return h >= 18 || h < 6;
  });

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: string, email: string) => {
    setUser({ role, email });
    setIsLoggedIn(true);
    setForcedPortal(true);
  };

  if (!isMobile && !forcedPortal) return <DesktopWebsite onEnterPortal={() => setForcedPortal(true)} />;
  if (!isLoggedIn) return <AuthGateway onLogin={handleLogin} darkMode={darkMode} />;

  if (currentPage === 'car-flow') return <CarInsuranceFlow onExit={() => setPage('home')} />;

