                                <h4 className="font-black text-2xl uppercase tracking-tighter">{p.title}</h4>
                                <p className="text-sm text-gray-500 dark:text-gray-400 font-medium mb-6 mt-2 leading-relaxed">{p.description}</p>
                                <div className="p-4 bg-primary-500/5 rounded-2xl border border-primary-500/20 text-[0.65rem] italic font-bold">"{p.sentimentSummary}"</div>
