export const verifyVehicleSurvey = async (images: { label: string, base64: string }[]): Promise<{ success: boolean; data?: VehicleVerificationData; error?: string }> => {
  const modelId = 'gemini-3-flash-preview';
  const prompt = `Anda adalah inspektur asuransi AI. Verifikasi foto-foto survey kendaraan berikut (Depan, Belakang, Kanan, Kiri, Interior).

  Kriteria Scoring Ketat:
  1. Deteksi Kerusakan Dini / Baret (Penting)
  2. Kejelasan Foto (Gelap/Blur)
  3. Indikasi Editan
  4. Konsistensi Kendaraan antar sisi

  Berikan output JSON:
  {
    "overallScore": number (0-100),
    "carConditionScore": number (0-100),
    "detectedIssues": ["string"],
    "insights": "string (Bahasa Indonesia)"
  }`;

  try {
    const parts = images.map(img => ({
      inlineData: { mimeType: 'image/jpeg', data: img.base64.split(',')[1] }
    }));

    const response = await ai.models.generateContent({
      model: modelId,
      contents: { parts: [{ text: prompt }, ...parts] },
      config: { responseMimeType: "application/json" }
    });

    return { success: true, data: JSON.parse(response.text) };
  } catch (error) {
    return { success: false, error: "Verifikasi Neural Gagal." };
  }
};

