const AuthGateway = ({ onLogin, darkMode }: { onLogin: (role: string, email: string) => void, darkMode: boolean }) => {
  const [view, setView] = useState<'login' | 'reset'>('login');
  const [role, setRole] = useState<'Member' | 'Partner' | 'Admin'>('Member');
  const [email, setEmail] = useState(localStorage.getItem('rememberedEmail') || '');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(!!localStorage.getItem('rememberedEmail'));
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loginSteps = ["Establishing Uplink...", "Querying Neural Core...", "Verifying Credentials...", "Access Granted."];

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 4) { setError("Insecure Access Key."); return; }
    setLoading(true);
    setTimeout(() => {
      if (rememberMe) localStorage.setItem('rememberedEmail', email);
      else localStorage.removeItem('rememberedEmail');
      setLoading(false);
      onLogin(role, email);
    }, 2000);
  };

  return (
    <div className={`fixed inset-0 z-[200] flex flex-col items-center justify-center p-6 ${darkMode ? 'bg-dark-bg' : 'bg-slate-50'}`}>
      <div className="relative w-full max-w-md glass-card rounded-[3.5rem] p-12 shadow-2xl border border-white/20 animate-pop-in">
        {loading ? (
          <InformativeNeuralLoader messages={loginSteps} />
        ) : (
          <div className="space-y-8">
            <div className="text-center">
               <ShieldCheck size={48} className="mx-auto text-primary-500 mb-4"/>
               <h1 className="font-black text-3xl tracking-tighter uppercase">Sure<span className="text-primary-500">Path</span></h1>
            </div>
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <input type="email" placeholder="EMAIL" className="w-full p-4 bg-slate-100 dark:bg-white/5 rounded-2xl outline-none" value={email} onChange={e => setEmail(e.target.value)} />
              <input type="password" placeholder="PASSWORD" className="w-full p-4 bg-slate-100 dark:bg-white/5 rounded-2xl outline-none" value={password} onChange={e => setPassword(e.target.value)} />
              <button className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">Login</button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const InformativeNeuralLoader = ({ messages }: { messages: string[] }) => {
  const [msgIndex, setMsgIndex] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setMsgIndex(prev => (prev + 1) % messages.length), 1500);
    return () => clearInterval(timer);
  }, [messages]);
  return (
    <div className="text-center space-y-6 py-10">
      <div className="relative w-20 h-20 mx-auto bg-primary-500/20 rounded-full flex items-center justify-center animate-pulse">
        <BrainCircuit size={40} className="text-primary-500" />
      </div>
      <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.3em]">{messages[msgIndex]}</p>
    </div>
  );
};

