                <h2 className="text-3xl font-black uppercase tracking-tighter">Pilihan <span className="text-primary-500">Perlindungan</span></h2>

                <div className="grid grid-cols-2 gap-4">
                   <button 
                    type="button"
                    onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.COMPREHENSIVE})}
                    className={`p-6 rounded-[2rem] border-2 transition-all ${vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? 'border-primary-500 bg-primary-500/5' : 'border-gray-200'}`}
                   >
                     <p className="font-black text-xs uppercase tracking-widest">Comprehensive</p>
                   </button>
                   <button 
                    type="button"
                    onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.TLO})}
                    className={`p-6 rounded-[2rem] border-2 transition-all ${vehicle.insuranceType === InsuranceType.TLO ? 'border-primary-500 bg-primary-500/5' : 'border-gray-200'}`}
                   >
                     <p className="font-black text-xs uppercase tracking-widest">TLO</p>
                   </button>
                </div>

                <div className="space-y-4">
                    <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-[0.2em] ml-2">Perluasan Jaminan (OJK)</p>
                    <div className="grid gap-3">
                        {[
                            { id: 'flood', label: 'Banjir & Badai' },
                            { id: 'earthquake', label: 'Gempa Bumi & Tsunami' },
                            { id: 'srcc', label: 'Kerusuhan (SRCC)' },
                            { id: 'terrorism', label: 'Terorisme & Sabotase' },
                            { id: 'authorizedWorkshop', label: 'Bengkel Authorized (+0.2%)' }
                        ].map(exp => (
                            <label key={exp.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-white/5 rounded-2xl cursor-pointer hover:bg-gray-100 transition-colors">
                                <span className="text-sm font-bold uppercase tracking-tight">{exp.label}</span>
                                <input 
                                    type="checkbox" 
                                    checked={(vehicle.expansions as any)[exp.id]} 
                                    onChange={e => setVehicle({ ...vehicle, expansions: { ...vehicle.expansions, [exp.id]: e.target.checked } })}
                                    className="w-5 h-5 accent-primary-500"
                                />
                            </label>
                        ))}
                        <div className="p-4 bg-gray-50 dark:bg-white/5 rounded-2xl">
                            <p className="text-[0.6rem] font-black uppercase text-gray-400 mb-2">TPL (Tanggung Jawab Hukum Pihak ke-3)</p>
                            <select className="w-full bg-transparent outline-none text-sm font-bold" value={vehicle.expansions.tpl} onChange={e => setVehicle({...vehicle, expansions: {...vehicle.expansions, tpl: parseInt(e.target.value)}})}>
                                {TPL_OPTIONS.map(opt => <option key={opt} value={opt}>{opt === 0 ? 'None' : formatIDR(opt)}</option>)}
                            </select>
                        </div>
                    </div>
                </div>

                <button type="submit" className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-[0.2em]">Cari Asuransi</button>
            </form>
        );

      case CarInsuranceStep.SELECT_PROVIDER:
        return (
            <div className="p-6 space-y-10 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Pilih <span className="text-primary-500">Asuransi</span></h2>
                <div className="grid gap-6">
                    {INSURANCE_PROVIDERS.map(p => (
                        <div key={p.id} className="p-8 glass-card rounded-[3rem] border border-black/5 space-y-6">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-primary-500 text-white rounded-2xl flex items-center justify-center"><p.logo size={24}/></div>
                                    <h4 className="font-black text-xl uppercase tracking-tighter">{p.name}</h4>
                                </div>
                                <div className="text-right">
                                    <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest">Premium Est.</p>
                                    <p className="text-2xl font-black text-primary-500">{formatIDR(calculateTotalPremium(vehicle, p))}</p>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 gap-4 border-t pt-6 text-[0.65rem] font-bold uppercase tracking-wider">
                                <div>
                                    <p className="text-emerald-500 mb-2">Kelebihan:</p>
                                    <ul className="space-y-1 text-gray-500">
                                        {p.advantages.map((a, i) => <li key={i} className="flex items-start gap-1">• {a}</li>)}
                                    </ul>
                                </div>
                                <div>
                                    <p className="text-rose-500 mb-2">Kekurangan:</p>
                                    <ul className="space-y-1 text-gray-500">
                                        {p.disadvantages.map((d, i) => <li key={i} className="flex items-start gap-1">• {d}</li>)}
                                    </ul>
                                </div>
                            </div>

                            <div className="flex items-center justify-between bg-primary-500/10 p-4 rounded-2xl">
                                <div>
                                    <p className="text-[0.55rem] font-black text-primary-600 uppercase">Extra Path Coins</p>
                                    <p className="text-sm font-black text-primary-600">+{p.extraCoinsPercent}% Reward</p>
                                </div>
                                <button 
                                    onClick={() => handleProviderSelect(p)}
                                    className="px-6 py-2 bg-primary-500 text-white rounded-xl text-[0.6rem] font-black uppercase"
                                >
                                    Pilih
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );

      case CarInsuranceStep.PRELIMINARY_SUMMARY:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-32">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Summary <span className="text-primary-500">Draft</span></h2>
                <div className="p-8 glass-card rounded-[3.5rem] border-2 border-primary-500/20 space-y-6">
                    <div className="space-y-2 border-b pb-4">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Detail Kendaraan</p>
                        <h4 className="text-xl font-black uppercase">{vehicle.brand} {vehicle.model}</h4>
                        <p className="text-sm font-bold text-gray-500">{vehicle.plate} • {vehicle.year} • {vehicle.usage}</p>
                    </div>
                    <div className="space-y-2 border-b pb-4">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Rincian Biaya</p>
                        <div className="flex justify-between text-sm"><span>Asuransi:</span> <span className="font-bold">{vehicle.selectedProvider?.name}</span></div>
                        <div className="flex justify-between text-sm"><span>Biaya Admin:</span> <span className="font-bold">{formatIDR(vehicle.selectedProvider?.adminFee || 0)}</span></div>
                        <div className="flex justify-between text-sm"><span>Materai:</span> <span className="font-bold">{formatIDR(STAMP_DUTY)}</span></div>
                    </div>
                    <div className="pt-2">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest mb-1">Total Premi</p>
                        <p className="text-4xl font-black text-primary-500 tracking-tighter">{formatIDR(calculateTotalPremium(vehicle, vehicle.selectedProvider))}</p>
                    </div>
                </div>

                <div className="grid gap-4">
                    <button onClick={handlePrint} className="w-full py-5 bg-gray-900 text-white rounded-3xl font-black uppercase tracking-widest flex items-center justify-center gap-3">
                        <Printer size={20}/> Simpan Sebagai PDF
                    </button>
                    <button onClick={() => setStep(CarInsuranceStep.KYC_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">
                        Lanjut Upload Data
                    </button>
                </div>
            </div>
        );

      case CarInsuranceStep.KYC_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Data <span className="text-primary-500">Nasabah</span></h2>
                <div className="aspect-video relative rounded-[2rem] overflow-hidden bg-gray-100 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer">
                    {user.ktpPhoto ? (
                        <img src={user.ktpPhoto} className="w-full h-full object-cover" />
                    ) : (
                        <>
                            <Camera size={48} className="text-gray-400 group-hover:text-primary-500 transition-colors"/>
