                {loading ? <InformativeNeuralLoader messages={["Analyzing KTP Document...", "Extracting Bio-data..."]} /> : (
                    <div className="space-y-4">
                        <input placeholder="Nama Sesuai KTP" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.name} onChange={e => setUser({...user, name: e.target.value})} />
                        <input placeholder="No. KTP" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.ktpNo} onChange={e => setUser({...user, ktpNo: e.target.value})} />
                        <input placeholder="Email" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.email} onChange={e => setUser({...user, email: e.target.value})} />
                        <input placeholder="Nomor Handphone" className="w-full p-4 bg-gray-100 rounded-2xl font-bold" value={user.phone} onChange={e => setUser({...user, phone: e.target.value})} />
                        <button onClick={() => setStep(CarInsuranceStep.VEHICLE_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest mt-6">Lanjut</button>
                    </div>
                )}
            </div>
        );

      case CarInsuranceStep.VEHICLE_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Survei <span className="text-primary-500">Kendaraan</span></h2>

                <div className="space-y-6">
                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Dokumen</p>
                        <div className="aspect-video relative rounded-2xl bg-gray-100 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center">
