                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('stnk', e)} />
                        </div>
                    </div>

                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Kondisi Mobil</p>
                        <div className="grid grid-cols-2 gap-4">
                            {[
                                { id: 'carFront', label: 'Tampak Depan' },
                                { id: 'carBack', label: 'Tampak Belakang' },
                                { id: 'carLeft', label: 'Sisi Kiri' },
                                { id: 'carRight', label: 'Sisi Kanan' },
                                { id: 'interior', label: 'Interior' }
                            ].map(item => (
                                <div key={item.id} className="aspect-square relative rounded-2xl bg-gray-100 border border-gray-200 flex flex-col items-center justify-center overflow-hidden">
                                    {(vehicle.photos as any)[item.id] ? <img src={(vehicle.photos as any)[item.id]} className="w-full h-full object-cover" /> : <><Camera size={20} className="text-gray-300"/><span className="text-[0.5rem] font-bold text-gray-400 mt-1">{item.label}</span></>}
                                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload(item.id as any, e)} />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <button 
                    disabled={!Object.values(vehicle.photos).every(v => v !== null)}
                    onClick={() => { runVerification(); setStep(CarInsuranceStep.SURVEY_VERIFICATION); }}
                    className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest disabled:opacity-50"
                >
                    Klik Verifikasi AI
                </button>
            </div>
        );

      case CarInsuranceStep.SURVEY_VERIFICATION:
        return (
            <div className="p-6 space-y-10 animate-fade-in text-center">
                {verifying ? <InformativeNeuralLoader messages={["Checking Damage...", "Analyzing Photo Clarity...", "Verifying Policy Consistency..."]} /> : (
                    <div className="space-y-8">
                        <div className="w-32 h-32 mx-auto relative">
                            <svg className="w-full h-full" viewBox="0 0 100 100">
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#eee" strokeWidth="10" />
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#10b981" strokeWidth="10" strokeDasharray={`${vehicle.aiVerificationScore || 0} ${100 - (vehicle.aiVerificationScore || 0)}`} strokeDashoffset="25" />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-3xl font-black text-primary-500">{vehicle.aiVerificationScore}</span>
                                <span className="text-[0.5rem] font-bold text-gray-400">SCORE</span>
                            </div>
                        </div>

                        { (vehicle.aiVerificationScore || 0) >= 80 ? (
                            <div className="space-y-6">
                                <h3 className="text-2xl font-black uppercase text-emerald-500">Verified Successfully</h3>
                                <p className="text-sm text-gray-500 px-6">Kendaraan dalam kondisi layak asuransi. Data STNK sesuai dengan input fisik.</p>
                                <button onClick={() => setStep(CarInsuranceStep.FINAL_CONFIRMATION)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">Lanjutkan</button>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                <div className="p-6 bg-rose-500/10 rounded-[2rem] border border-rose-500/20 flex items-center gap-4 text-left">
                                    <ShieldAlert className="text-rose-500" size={32}/>
                                    <div>
                                        <p className="text-sm font-black text-rose-500 uppercase">Verifikasi Gagal</p>
                                        <p className="text-xs text-rose-500/70">Skor di bawah 80. Foto kurang jelas atau terdeteksi kerusakan baret halus.</p>
                                    </div>
                                </div>
                                <button onClick={onExit} className="w-full py-5 bg-gray-900 text-white rounded-3xl font-black uppercase tracking-widest">Hubungi Admin (Verifikasi Manual)</button>
                                <button onClick={() => setStep(CarInsuranceStep.VEHICLE_UPLOAD)} className="text-[0.6rem] font-black uppercase text-primary-500 tracking-widest">Ambil Ulang Foto</button>
                            </div>
                        )}
                    </div>
                )}
            </div>
        );

      case CarInsuranceStep.FINAL_CONFIRMATION:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Konfirmasi <span className="text-primary-500">Pembelian</span></h2>

                <div className="space-y-6">
                    <div className="p-6 glass-card rounded-[2.5rem] space-y-4">
                        <div className="flex items-center gap-3"><User size={20} className="text-primary-500"/><span className="font-bold">{user.name}</span></div>
                        <div className="flex items-center gap-3"><Car size={20} className="text-primary-500"/><span className="font-bold">{vehicle.brand} {vehicle.model} ({vehicle.plate})</span></div>
                    </div>

                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest ml-2 mb-3">Pengiriman Polis</p>
                        <div className="grid grid-cols-3 gap-3">
                            {['WHATSAPP', 'EMAIL', 'HARDCOPY'].map(m => (
                                <button key={m} onClick={() => setUser({...user, deliveryMethod: m as any})} className={`py-4 rounded-2xl text-[0.55rem] font-black uppercase border-2 transition-all ${user.deliveryMethod === m ? 'border-primary-500 bg-primary-500/10 text-primary-600' : 'border-gray-100 text-gray-400'}`}>{m}</button>
                            ))}
                        </div>
                        {user.deliveryMethod === 'HARDCOPY' && (
                            <div className="mt-4 space-y-3">
                                <input placeholder="Nama Penerima" className="w-full p-4 bg-gray-100 rounded-2xl text-sm" onChange={e => setUser({...user, recipientName: e.target.value})} />
                                <textarea placeholder="Alamat Lengkap" className="w-full p-4 bg-gray-100 rounded-2xl text-sm h-24" onChange={e => setUser({...user, address: e.target.value})} />
                            </div>
                        )}
                    </div>
                </div>

                <div className="p-6 bg-gray-900 rounded-[2.5rem] text-white">
                    <p className="text-[0.6rem] font-black uppercase text-gray-400">Total Yang Dibayarkan</p>
                    <p className="text-3xl font-black text-primary-500">{formatIDR(calculateTotalPremium(vehicle, vehicle.selectedProvider))}</p>
                </div>

                <button onClick={() => setStep(CarInsuranceStep.PAYMENT)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-[0.2em] shadow-2xl">Lanjut ke Pembayaran</button>
            </div>
        );

      case CarInsuranceStep.PAYMENT:
        return (
            <div className="p-6 text-center space-y-8 py-20 animate-fade-in">
                <div className="w-20 h-20 bg-primary-500/10 rounded-3xl mx-auto flex items-center justify-center text-primary-500 animate-pulse"><CreditCard size={40}/></div>
                <h2 className="text-3xl font-black uppercase">Payment <span className="text-primary-500">Gateway</span></h2>
                <p className="text-sm text-gray-500">Menghubungkan ke sistem pembayaran aman SurePath...</p>
                <button onClick={() => setStep(CarInsuranceStep.SUCCESS)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest mt-10">Bayar Sekarang</button>
            </div>
        );

      case CarInsuranceStep.SUCCESS:
        return (
            <div className="p-6 text-center space-y-10 py-20 animate-fade-in">
                <div className="w-24 h-24 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/40 animate-pop-in"><Check size={48} strokeWidth={4}/></div>
                <div className="space-y-2">
                    <h2 className="text-4xl font-black uppercase">Pembayaran <span className="text-primary-500">Berhasil</span></h2>
                    <p className="text-gray-500 px-6">Polis digital sedang dikirimkan ke {user.deliveryMethod === 'EMAIL' ? user.email : 'nomor WhatsApp Anda'}.</p>
                </div>
                <button onClick={onExit} className="w-full py-5 bg-gray-900 text-white rounded-3xl font-black uppercase tracking-widest mt-10">Kembali ke Home</button>
            </div>
        );

      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white pb-32">
        <header className="h-20 glass-card px-6 flex items-center justify-between border-b border-black/5">
            <button onClick={onExit} className="w-10 h-10 bg-gray-100 dark:bg-white/5 rounded-xl flex items-center justify-center text-gray-500"><ChevronLeft size={24}/></button>
            <div className="flex items-center gap-2"><div className="w-8 h-8 bg-primary-500 rounded-lg flex items-center justify-center text-white"><Car size={18}/></div><span className="font-black text-sm uppercase tracking-widest">Car Insurance</span></div>
            <div className="w-10"></div>
        </header>
        <main className="max-w-lg mx-auto">{renderStepContent()}</main>
    </div>
  );
};

// --- MAIN APP ---

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState<{ role: string, email: string } | null>(null);
  const [forcedPortal, setForcedPortal] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [darkMode, setDarkMode] = useState(() => {
    const h = new Date().getHours();
    return h >= 18 || h < 6;
  });

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: string, email: string) => {
    setUser({ role, email });
    setIsLoggedIn(true);
    setForcedPortal(true);
  };

  if (!isMobile && !forcedPortal) return <DesktopWebsite onEnterPortal={() => setForcedPortal(true)} />;
  if (!isLoggedIn) return <AuthGateway onLogin={handleLogin} darkMode={darkMode} />;

  if (currentPage === 'car-flow') return <CarInsuranceFlow onExit={() => setPage('home')} />;

  return (
    <div className={`min-h-screen ${darkMode ? 'dark bg-dark-bg text-white' : 'bg-slate-50 text-gray-900'}`}>
        <header className="sticky top-0 z-40 h-20 glass-card px-6 flex items-center justify-between border-b border-black/5 dark:border-white/5">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white shadow-lg"><ShieldCheck size={24}/></div>
                <span className="font-black text-xl tracking-tighter uppercase">Sure<span className="text-primary-500">Path</span></span>
            </div>
            <div className="flex items-center gap-3">
                <button onClick={() => setDarkMode(!darkMode)} className="p-2.5 bg-gray-100 dark:bg-white/5 rounded-xl text-slate-400">{darkMode ? <Sun size={18}/> : <Moon size={18}/>}</button>
                <div className="w-10 h-10 rounded-xl border border-black/10 overflow-hidden"><img src={`https://i.pravatar.cc/100?u=${user?.email}`} className="w-full h-full object-cover" /></div>
            </div>
        </header>

        <main className="max-w-lg mx-auto p-6 space-y-10 animate-fade-in pb-32">
            {currentPage === 'home' && (
                <>
                    <div className="relative h-80 rounded-[3.5rem] overflow-hidden shadow-2xl group border border-white/10">
                        <img src="https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?q=80&w=800" className="absolute inset-0 w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/95 p-12 flex flex-col justify-end">
                            <h1 className="text-4xl font-black text-white leading-none tracking-tighter uppercase">Automated <br/> <span className="text-primary-500">Protection</span></h1>
                            <button onClick={() => setPage('car-flow')} className="mt-6 px-8 py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-widest w-fit">Get Quote</button>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div onClick={() => setPage('products')} className="p-8 glass-card rounded-[3rem] text-left border border-black/5 shadow-lg cursor-pointer">
                            <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-6"><Grid size={28}/></div>
                            <p className="font-black text-2xl uppercase tracking-tighter leading-none">Market <br/> Place</p>
                        </div>
                        <div onClick={() => setPage('car-flow')} className="p-8 glass-card rounded-[3rem] text-left border border-black/5 shadow-lg cursor-pointer">
                            <div className="w-14 h-14 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mb-6"><Zap size={28}/></div>
                            <p className="font-black text-2xl uppercase tracking-tighter leading-none">Instant <br/> Quote</p>
                        </div>
                    </div>
                </>
            )}

            {currentPage === 'products' && (
                <div className="space-y-10">
                    <h2 className="text-3xl font-black uppercase tracking-tighter">Neural <span className="text-primary-500">Store</span></h2>
                    <div className="grid gap-8">
