    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      if (field === 'ktp') {
          setUser({ ...user, ktpPhoto: base64 });
          setLoading(true);
          const res = await extractKtpData(base64);
          if (res.success) {
              setUser(prev => ({ ...prev, name: res.data.nama || '', ktpNo: res.data.noKtp || prev.ktpNo, address: res.data.alamat || prev.address }));
          }
          setLoading(false);
      } else if (field === 'stnk') {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
          setLoading(true);
          const res = await extractStnkData(base64);
          if (res.success) {
              // Extract logic
          }
          setLoading(false);
      } else {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
      }
    };
    reader.readAsDataURL(file);
  };

  const runVerification = async () => {
    setVerifying(true);
    const photos = Object.entries(vehicle.photos)
        .filter(([k, v]) => k !== 'stnk' && v !== null)
        .map(([k, v]) => ({ label: k, base64: v as string }));

