                    value={vehicle.brand}
                    onChange={e => {
                        const brand = e.target.value;
                        setVehicle({ ...vehicle, brand, isOther: brand === 'OTHERS', model: '' });
                    }}
                  >
                    <option value="">Pilih Merk</option>
                    {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    <option value="OTHERS">Others (Freetype)</option>
                  </select>
                  {vehicle.isOther && <input placeholder="Input Merk" className="w-full mt-2 p-4 border border-primary-500/20 rounded-xl dark:bg-white/5 dark:text-white" onChange={e => setVehicle({...vehicle, brand: e.target.value})} />}
               </div>

               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Tipe / Model</label>
                  {!vehicle.isOther ? (
