// --- AUTH GATEWAY ---

const AuthGateway = ({ onLogin, darkMode }: { onLogin: (role: string, email: string) => void, darkMode: boolean }) => {
  const [view, setView] = useState<'login' | 'reset'>('login');
  const [role, setRole] = useState<'Member' | 'Partner' | 'Admin'>('Member');
  const [email, setEmail] = useState(localStorage.getItem('rememberedEmail') || '');
  const [password, setPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(!!localStorage.getItem('rememberedEmail'));
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const loginSteps = ["Establishing Uplink...", "Querying Neural Core...", "Verifying Credentials...", "Access Granted."];

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (password.length < 4) { setError("Insecure Access Key."); return; }
    setLoading(true);
    setTimeout(() => {
      if (rememberMe) localStorage.setItem('rememberedEmail', email);
      else localStorage.removeItem('rememberedEmail');
      setLoading(false);
      onLogin(role, email);
    }, 2000);
  };

  return (
    <div className={`fixed inset-0 z-[200] flex flex-col items-center justify-center p-6 ${darkMode ? 'bg-dark-bg' : 'bg-slate-50'}`}>
      <div className="relative w-full max-w-md glass-card rounded-[3.5rem] p-12 shadow-2xl border border-white/20 animate-pop-in">
        {loading ? (
          <InformativeNeuralLoader messages={loginSteps} />
        ) : (
          <div className="space-y-8">
            <div className="text-center">
               <ShieldCheck size={48} className="mx-auto text-primary-500 mb-4"/>
               <h1 className="font-black text-3xl tracking-tighter uppercase dark:text-white">Sure<span className="text-primary-500">Path</span></h1>
            </div>
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <input type="email" placeholder="EMAIL" className="w-full p-4 bg-slate-100/50 dark:bg-white/5 rounded-2xl outline-none text-slate-700 dark:text-slate-200" value={email} onChange={e => setEmail(e.target.value)} />
              <input type="password" placeholder="PASSWORD" className="w-full p-4 bg-slate-100/50 dark:bg-white/5 rounded-2xl outline-none text-slate-700 dark:text-slate-200" value={password} onChange={e => setPassword(e.target.value)} />
              <button className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest shadow-lg shadow-primary-500/20 active:scale-95 transition-transform">Login</button>
            </form>
          </div>
        )}
      </div>
    </div>
  );
};

const InformativeNeuralLoader = ({ messages }: { messages: string[] }) => {
  const [msgIndex, setMsgIndex] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setMsgIndex(prev => (prev + 1) % messages.length), 1500);
    return () => clearInterval(timer);
  }, [messages]);
  return (
    <div className="text-center space-y-6 py-10">
      <div className="relative w-20 h-20 mx-auto bg-primary-500/20 rounded-full flex items-center justify-center animate-pulse">
        <BrainCircuit size={40} className="text-primary-500" />
      </div>
      <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-[0.3em]">{messages[msgIndex]}</p>
    </div>
  );
};

// --- CAR INSURANCE FLOW ---

const CarInsuranceFlow = ({ onExit }: { onExit: () => void }) => {
  const [step, setStep] = useState<CarInsuranceStep>(CarInsuranceStep.VEHICLE_DATA);
  const [vehicle, setVehicle] = useState<VehicleState>({
    brand: '', model: '', isOther: false, year: 2024, price: 0, manualPrice: false, plate: '', region: '2',
    usage: 'PRIVATE', condition: 'NEW', insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: true, tpl: 0, paDriver: false, paPassenger: false },
    promoCode: '', discount: 0, discountType: 'PERCENT', selectedProvider: null,
    photos: { stnk: null, carFront: null, carBack: null, carLeft: null, carRight: null, interior: null }
  });
  const [user, setUser] = useState<UserState>({
    name: '', ktpNo: '', email: '', phone: '', address: '', recipientName: '', deliveryMethod: 'EMAIL', ktpPhoto: null
  });
  const [loading, setLoading] = useState(false);
  const [verifying, setVerifying] = useState(false);

  // Helper: Calculate Premium
  const calculateTotalPremium = (v: VehicleState, provider: Provider | null) => {
    if (!provider) return 0;
    const priceMillions = v.price / 1000000;
    const baseRate = getOJKRate(priceMillions, v.region, v.insuranceType);
    let totalRate = baseRate;

    if (v.expansions.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (v.expansions.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;
    // fix: use dynamic insuranceType to select the correct expansion rate from constants
    if (v.expansions.srcc) totalRate += (EXPANSION_RATES.SRCC as any)[v.insuranceType];
    // fix: use dynamic insuranceType to select the correct expansion rate from constants
    if (v.expansions.terrorism) totalRate += (EXPANSION_RATES.TERRORISM as any)[v.insuranceType];
    if (v.expansions.authorizedWorkshop) totalRate += 0.2; // Based on doc

    let premium = (totalRate / 100) * v.price;
    premium += v.expansions.tpl * 1000000; // TPL logic

    const total = premium + provider.adminFee + STAMP_DUTY;
    return total;
  };

  const handleStep1 = (e: React.FormEvent) => {
    e.preventDefault();
    setStep(CarInsuranceStep.COVERAGE);
  };

  const handleStep2 = (e: React.FormEvent) => {
    e.preventDefault();
    setStep(CarInsuranceStep.SELECT_PROVIDER);
  };

  const handleProviderSelect = (p: Provider) => {
    setVehicle({ ...vehicle, selectedProvider: p });
    setStep(CarInsuranceStep.PRELIMINARY_SUMMARY);
  };

  const handleFileUpload = (field: keyof VehiclePhotos | 'ktp', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      if (field === 'ktp') {
          setUser({ ...user, ktpPhoto: base64 });
          setLoading(true);
          const res = await extractKtpData(base64);
          if (res.success) {
              setUser(prev => ({ ...prev, name: res.data.nama || '', ktpNo: res.data.noKtp || prev.ktpNo, address: res.data.alamat || prev.address }));
          }
          setLoading(false);
      } else if (field === 'stnk') {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
          setLoading(true);
          const res = await extractStnkData(base64);
          if (res.success) {
              // Extract logic
          }
          setLoading(false);
      } else {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
      }
    };
    reader.readAsDataURL(file);
  };

  const runVerification = async () => {
    setVerifying(true);
    const photos = Object.entries(vehicle.photos)
        .filter(([k, v]) => k !== 'stnk' && v !== null)
        .map(([k, v]) => ({ label: k, base64: v as string }));

    const res = await verifyVehicleSurvey(photos);
    if (res.success && res.data) {
        setVehicle({ ...vehicle, aiVerificationScore: res.data.overallScore });
    }
    setVerifying(false);
  };

  const handlePrint = () => { window.print(); };

  const renderStepContent = () => {
    switch(step) {
      case CarInsuranceStep.VEHICLE_DATA:
        return (
          <form onSubmit={handleStep1} className="space-y-8 animate-fade-in p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Data <span className="text-primary-500">Kendaraan</span></h2>

            <div className="space-y-4">
               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Merk Mobil</label>
                  <select 
                    className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white"
                    value={vehicle.brand}
                    onChange={e => {
                        const brand = e.target.value;
                        setVehicle({ ...vehicle, brand, isOther: brand === 'OTHERS', model: '' });
                    }}
                  >
                    <option value="">Pilih Merk</option>
                    {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    <option value="OTHERS">Others (Freetype)</option>
                  </select>
                  {vehicle.isOther && <input placeholder="Input Merk" className="w-full mt-2 p-4 border border-primary-500/20 rounded-xl dark:bg-white/5 dark:text-white" onChange={e => setVehicle({...vehicle, brand: e.target.value})} />}
               </div>

               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Tipe / Model</label>
                  {!vehicle.isOther ? (
                    <select 
                        className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white"
                        value={vehicle.model}
                        onChange={e => {
                            const modelData = CAR_DATABASE.find(c => c.code === e.target.value);
                            if (modelData) {
                                setVehicle({ ...vehicle, model: modelData.code, price: (modelData.yearPrices[vehicle.year] || 0) * 1000000 });
                            }
                        }}
                    >
                        <option value="">Pilih Model</option>
                        {CAR_DATABASE.filter(c => c.brand === vehicle.brand).map(c => <option key={c.code} value={c.code}>{c.modelName}</option>)}
                    </select>
                  ) : (
                    <input placeholder="Input Model" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white" onChange={e => setVehicle({...vehicle, model: e.target.value})} />
                  )}
               </div>

               <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Tahun</label>
                    <input type="number" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl dark:text-white" value={vehicle.year} onChange={e => setVehicle({...vehicle, year: parseInt(e.target.value)})} />
                  </div>
                  <div>
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Kondisi</label>
                    <select className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl dark:text-white" value={vehicle.condition} onChange={e => setVehicle({...vehicle, condition: e.target.value as any})}>
                      <option value="NEW">Baru</option>
                      <option value="USED">Bekas</option>
                    </select>
                  </div>
               </div>

               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Harga Kendaraan (IDR)</label>
                  <input 
                    type="number" 
                    className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl dark:text-white" 
                    value={vehicle.price} 
                    onChange={e => setVehicle({...vehicle, price: parseInt(e.target.value), manualPrice: true})} 
                  />
                  <p className="text-[0.55rem] text-gray-400 mt-1 ml-2">Range: +/- 10% dari pricelist diperbolehkan</p>
               </div>

               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Nomor Plat (AA-BBBB-CCC)</label>
                  <input 
                    placeholder="Contoh: B-1234-XYZ" 
                    className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl uppercase dark:text-white" 
                    value={vehicle.plate} 
                    onChange={e => {
                        const val = e.target.value;
                        const regionCode = val.split('-')[0].toUpperCase();
                        setVehicle({ ...vehicle, plate: val, region: PLATE_REGIONS[regionCode] || '3' });
                    }} 
                  />
               </div>
            </div>

            <button type="submit" className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-xl shadow-primary-500/20">Lanjutkan</button>
          </form>
        );

      case CarInsuranceStep.COVERAGE:
        return (
            <form onSubmit={handleStep2} className="space-y-8 animate-fade-in p-6 pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Pilihan <span className="text-primary-500">Perlindungan</span></h2>

                <div className="grid grid-cols-2 gap-4">
                   <button 
                    type="button"
                    onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.COMPREHENSIVE})}
                    className={`p-6 rounded-[2rem] border-2 transition-all ${vehicle.insuranceType === InsuranceType.COMPREHENSIVE ? 'border-primary-500 bg-primary-500/5' : 'border-gray-200 dark:border-white/10'}`}
                   >
                     <p className="font-black text-xs uppercase tracking-widest dark:text-white">Comprehensive</p>
                   </button>
                   <button 
                    type="button"
                    onClick={() => setVehicle({...vehicle, insuranceType: InsuranceType.TLO})}
                    className={`p-6 rounded-[2rem] border-2 transition-all ${vehicle.insuranceType === InsuranceType.TLO ? 'border-primary-500 bg-primary-500/5' : 'border-gray-200 dark:border-white/10'}`}
                   >
                     <p className="font-black text-xs uppercase tracking-widest dark:text-white">TLO</p>
                   </button>
                </div>

                <div className="space-y-4">
                    <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-[0.2em] ml-2">Perluasan Jaminan (OJK)</p>
                    <div className="grid gap-3">
                        {[
                            { id: 'flood', label: 'Banjir & Badai' },
                            { id: 'earthquake', label: 'Gempa Bumi & Tsunami' },
                            { id: 'srcc', label: 'Kerusuhan (SRCC)' },
                            { id: 'terrorism', label: 'Terorisme & Sabotase' },
                            { id: 'authorizedWorkshop', label: 'Bengkel Authorized (+0.2%)' }
                        ].map(exp => (
                            <label key={exp.id} className="flex items-center justify-between p-4 bg-gray-50 dark:bg-white/5 rounded-2xl cursor-pointer hover:bg-gray-100 dark:hover:bg-white/10 transition-colors">
                                <span className="text-sm font-bold uppercase tracking-tight dark:text-white">{exp.label}</span>
                                <input 
                                    type="checkbox" 
                                    checked={(vehicle.expansions as any)[exp.id]} 
                                    onChange={e => setVehicle({ ...vehicle, expansions: { ...vehicle.expansions, [exp.id]: e.target.checked } })}
                                    className="w-5 h-5 accent-primary-500"
                                />
                            </label>
                        ))}
                    </div>
                </div>

                <button type="submit" className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-[0.2em]">Cari Asuransi</button>
            </form>
        );

      case CarInsuranceStep.SELECT_PROVIDER:
        return (
            <div className="p-6 space-y-10 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Pilih <span className="text-primary-500">Asuransi</span></h2>
                <div className="grid gap-6">
                    {INSURANCE_PROVIDERS.map(p => (
                        <div key={p.id} className="p-8 glass-card rounded-[3rem] border border-black/5 dark:border-white/5 space-y-6">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-primary-500 text-white rounded-2xl flex items-center justify-center"><p.logo size={24}/></div>
                                    <h4 className="font-black text-xl uppercase tracking-tighter dark:text-white">{p.name}</h4>
                                </div>
                                <div className="text-right">
                                    <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest">Premium Est.</p>
                                    <p className="text-2xl font-black text-primary-500">{formatIDR(calculateTotalPremium(vehicle, p))}</p>
                                </div>
                            </div>

                            <div className="flex items-center justify-between bg-primary-500/10 p-4 rounded-2xl">
                                <div>
                                    <p className="text-[0.55rem] font-black text-primary-600 uppercase">Extra Coins</p>
                                    <p className="text-sm font-black text-primary-600">+{p.extraCoinsPercent || 10}%</p>
                                </div>
                                <button 
                                    onClick={() => handleProviderSelect(p)}
                                    className="px-6 py-2 bg-primary-500 text-white rounded-xl text-[0.6rem] font-black uppercase"
                                >
                                    Pilih
                                </button>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        );

      case CarInsuranceStep.PRELIMINARY_SUMMARY:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-32">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Summary <span className="text-primary-500">Draft</span></h2>
                <div className="p-8 glass-card rounded-[3.5rem] border-2 border-primary-500/20 space-y-6">
                    <div className="space-y-2 border-b dark:border-white/10 pb-4">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest">Detail Kendaraan</p>
                        <h4 className="text-xl font-black uppercase dark:text-white">{vehicle.brand} {vehicle.model}</h4>
                    </div>
                    <div className="pt-2">
                        <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-widest mb-1">Total Premi</p>
                        <p className="text-4xl font-black text-primary-500 tracking-tighter">{formatIDR(calculateTotalPremium(vehicle, vehicle.selectedProvider))}</p>
                    </div>
                </div>

                <div className="grid gap-4">
                    <button onClick={handlePrint} className="w-full py-5 bg-gray-900 dark:bg-white dark:text-black text-white rounded-3xl font-black uppercase tracking-widest flex items-center justify-center gap-3 shadow-xl">
                        <Printer size={20}/> Simpan Sebagai PDF
                    </button>
                    <button onClick={() => setStep(CarInsuranceStep.KYC_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest shadow-lg">
                        Lanjut Upload Data
                    </button>
                </div>
            </div>
        );

      case CarInsuranceStep.KYC_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Data <span className="text-primary-500">Nasabah</span></h2>
                <div className="aspect-video relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
                    {user.ktpPhoto ? (
                        <img src={user.ktpPhoto} className="w-full h-full object-cover" />
                    ) : (
                        <>
                            <Camera size={48} className="text-gray-400 group-hover:text-primary-500 transition-colors"/>
                            <p className="text-[0.65rem] font-black uppercase text-gray-400 mt-2">Upload Foto KTP</p>
                        </>
                    )}
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('ktp', e)} />
                </div>

                <div className="space-y-4">
                    <input placeholder="Nama Sesuai KTP" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl font-bold dark:text-white" value={user.name} onChange={e => setUser({...user, name: e.target.value})} />
                    <input placeholder="No. KTP" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl font-bold dark:text-white" value={user.ktpNo} onChange={e => setUser({...user, ktpNo: e.target.value})} />
                    <button onClick={() => setStep(CarInsuranceStep.VEHICLE_UPLOAD)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest mt-6 shadow-lg">Lanjut</button>
                </div>
            </div>
        );

      case CarInsuranceStep.VEHICLE_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Survei <span className="text-primary-500">Kendaraan</span></h2>

                <div className="space-y-6">
                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Dokumen STNK</p>
                        <div className="aspect-video relative rounded-2xl bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center shadow-inner">
                            {vehicle.photos.stnk ? <img src={vehicle.photos.stnk} className="w-full h-full object-cover rounded-2xl" /> : <><ImageIcon size={32} className="text-gray-300"/><span className="text-[0.6rem] font-bold text-gray-400 mt-2">UPLOAD STNK</span></>}
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('stnk', e)} />
                        </div>
                    </div>

                    <div>
                        <p className="text-[0.65rem] font-black uppercase text-gray-400 tracking-widest mb-3 ml-2">Foto Kondisi (AI Vision Scan)</p>
                        <div className="grid grid-cols-2 gap-4">
                            {[
                                { id: 'carFront', label: 'Tampak Depan' },
                                { id: 'carBack', label: 'Tampak Belakang' },
                                { id: 'carLeft', label: 'Sisi Kiri' },
                                { id: 'carRight', label: 'Sisi Kanan' },
                                { id: 'interior', label: 'Interior' }
                            ].map(item => (
                                <div key={item.id} className="aspect-square relative rounded-2xl bg-gray-100 dark:bg-white/5 border border-gray-200 dark:border-white/10 flex flex-col items-center justify-center overflow-hidden">
                                    {(vehicle.photos as any)[item.id] ? <img src={(vehicle.photos as any)[item.id]} className="w-full h-full object-cover" /> : <><Camera size={20} className="text-gray-300"/><span className="text-[0.5rem] font-bold text-gray-400 mt-1">{item.label}</span></>}
                                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload(item.id as any, e)} />
                                </div>
                            ))}
                        </div>
                    </div>
                </div>

                <button 
                    disabled={!Object.values(vehicle.photos).every(v => v !== null)}
                    onClick={() => { runVerification(); setStep(CarInsuranceStep.SURVEY_VERIFICATION); }}
                    className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest disabled:opacity-50 shadow-lg"
                >
                    Run Neural Audit
                </button>
            </div>
        );

      case CarInsuranceStep.SURVEY_VERIFICATION:
        return (
            <div className="p-6 space-y-10 animate-fade-in text-center">
                {verifying ? <InformativeNeuralLoader messages={["Checking Damage...", "Analyzing Photo Clarity...", "Verifying Policy Consistency..."]} /> : (
                    <div className="space-y-8">
                        <div className="w-32 h-32 mx-auto relative">
                            <svg className="w-full h-full" viewBox="0 0 100 100">
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#eee" strokeWidth="10" className="opacity-10" />
                                <circle cx="50" cy="50" r="45" fill="none" stroke="#10b981" strokeWidth="10" strokeDasharray={`${vehicle.aiVerificationScore || 0} ${100 - (vehicle.aiVerificationScore || 0)}`} strokeDashoffset="25" className="transition-all duration-1000" />
                            </svg>
                            <div className="absolute inset-0 flex flex-col items-center justify-center">
                                <span className="text-3xl font-black text-primary-500">{vehicle.aiVerificationScore}</span>
                                <span className="text-[0.5rem] font-bold text-gray-400 uppercase">SCORE</span>
                            </div>
                        </div>

                        { (vehicle.aiVerificationScore || 0) >= 80 ? (
                            <div className="space-y-6">
                                <h3 className="text-2xl font-black uppercase text-emerald-500">Neural Verification Pass</h3>
                                <p className="text-sm text-gray-500 dark:text-gray-400 px-6">Damage audit complete. Vehicle integrity verified at 99.4% confidence interval.</p>
                                <button onClick={() => setStep(CarInsuranceStep.FINAL_CONFIRMATION)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest shadow-lg">Lanjutkan</button>
                            </div>
                        ) : (
                            <div className="space-y-6">
                                <div className="p-6 bg-rose-500/10 rounded-[2rem] border border-rose-500/20 flex items-center gap-4 text-left">
                                    <ShieldAlert className="text-rose-500" size={32}/>
                                    <div>
                                        <p className="text-sm font-black text-rose-500 uppercase">Verification Anomalies</p>
                                        <p className="text-xs text-rose-500/70">Score below neural threshold (80). Possible damage detected or low photo clarity.</p>
                                    </div>
                                </div>
                                <button onClick={onExit} className="w-full py-5 bg-gray-900 dark:bg-white dark:text-black text-white rounded-3xl font-black uppercase tracking-widest">Manual Audit via Admin</button>
                                <button onClick={() => setStep(CarInsuranceStep.VEHICLE_UPLOAD)} className="text-[0.6rem] font-black uppercase text-primary-500 tracking-widest">Retake Survey Photos</button>
                            </div>
                        )}
                    </div>
                )}
            </div>
        );

      case CarInsuranceStep.FINAL_CONFIRMATION:
        return (
            <div className="p-6 space-y-8 animate-fade-in pb-24">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Konfirmasi <span className="text-primary-500">Pembelian</span></h2>
                <div className="p-6 bg-gray-900 dark:bg-white rounded-[2.5rem] text-white dark:text-black shadow-xl">
                    <p className="text-[0.6rem] font-black uppercase opacity-60">Payout Matrix</p>
                    <p className="text-3xl font-black text-primary-500">{formatIDR(calculateTotalPremium(vehicle, vehicle.selectedProvider))}</p>
                </div>
                <button onClick={() => setStep(CarInsuranceStep.SUCCESS)} className="w-full py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase tracking-[0.2em] shadow-2xl">Confirm & Pay</button>
            </div>
        );

      case CarInsuranceStep.SUCCESS:
        return (
            <div className="p-6 text-center space-y-10 py-20 animate-fade-in">
                <div className="w-24 h-24 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/40 animate-pop-in"><Check size={48} strokeWidth={4}/></div>
                <div className="space-y-2">
                    <h2 className="text-4xl font-black uppercase dark:text-white">Link <span className="text-primary-500">Established</span></h2>
                    <p className="text-gray-500 dark:text-gray-400 px-6">Policy matrix deployed. Your digital certificate has been transmitted via email.</p>
                </div>
                <button onClick={onExit} className="w-full py-5 bg-gray-900 dark:bg-white dark:text-black text-white rounded-3xl font-black uppercase tracking-widest mt-10 shadow-xl">Return to Hub</button>
            </div>
        );

      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white pb-32">
        <header className="h-20 glass-card px-6 flex items-center justify-between border-b border-black/5 dark:border-white/5">
            <button onClick={onExit} className="w-10 h-10 bg-gray-100 dark:bg-white/5 rounded-xl flex items-center justify-center text-gray-500 dark:text-gray-300"><ChevronLeft size={24}/></button>
            <div className="flex items-center gap-2"><div className="w-8 h-8 bg-primary-500 rounded-lg flex items-center justify-center text-white"><Car size={18}/></div><span className="font-black text-sm uppercase tracking-widest dark:text-white">Configurator</span></div>
            <div className="w-10"></div>
        </header>
        <main className="max-w-lg mx-auto">{renderStepContent()}</main>
    </div>
  );
};

// --- MAIN APP COMPONENT ---

const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [user, setUser] = useState<{ role: string, email: string } | null>(null);
  const [forcedPortal, setForcedPortal] = useState(false);
  const [currentPage, setPage] = useState('home');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [darkMode, setDarkMode] = useState(() => {
    const h = new Date().getHours();
    return h >= 18 || h < 6;
  });

  const [isAnalyzingClaim, setIsAnalyzingClaim] = useState(false);
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleLogin = (role: string, email: string) => {
    setUser({ role, email });
    setIsLoggedIn(true);
    setForcedPortal(true);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsAnalyzingClaim(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await analyzeClaimPhoto(base64);
      if (response.success && response.data) setClaimResult(response.data);
      setIsAnalyzingClaim(false);
    };
    reader.readAsDataURL(file);
  };

  if (!isMobile && !forcedPortal) return <DesktopWebsite onEnterPortal={() => setForcedPortal(true)} />;
  if (!isLoggedIn) return <AuthGateway onLogin={handleLogin} darkMode={darkMode} />;

  if (currentPage === 'car-flow') return <CarInsuranceFlow onExit={() => setPage('home')} />;

  return (
    <div className={`min-h-screen ${darkMode ? 'dark bg-dark-bg text-white' : 'bg-slate-50 text-gray-900'} transition-colors duration-500`}>
        <header className="sticky top-0 z-40 h-20 glass-card px-6 flex items-center justify-between border-b border-black/5 dark:border-white/5">
            <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white shadow-lg"><ShieldCheck size={24}/></div>
                <span className="font-black text-xl tracking-tighter uppercase dark:text-white">Sure<span className="text-primary-500">Path</span></span>
            </div>
            <div className="flex items-center gap-3">
                <button onClick={() => { setDarkMode(!darkMode); if(!darkMode) document.body.classList.add('dark'); else document.body.classList.remove('dark'); }} className="p-2.5 bg-gray-100 dark:bg-white/5 rounded-xl text-slate-400">
                  {darkMode ? <Sun size={18}/> : <Moon size={18}/>}
                </button>
                <div className="w-10 h-10 rounded-xl border border-black/10 dark:border-white/10 overflow-hidden shadow-sm"><img src={`https://i.pravatar.cc/100?u=${user?.email}`} className="w-full h-full object-cover" /></div>
            </div>
        </header>

        <main className="max-w-lg mx-auto p-6 pb-32 animate-fade-in">
            {currentPage === 'home' && (
                <div className="space-y-10">
                    <div className="relative h-80 rounded-[3.5rem] overflow-hidden shadow-2xl group border border-white/10">
                        <img src="https://images.unsplash.com/photo-1549317661-bd32c8ce0db2?q=80&w=800" className="absolute inset-0 w-full h-full object-cover" />
                        <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/40 to-transparent p-12 flex flex-col justify-end">
                            <p className="text-[0.6rem] font-bold text-primary-400 uppercase tracking-[0.5em] mb-2">Neural Protection 3.0</p>
                            <h1 className="text-4xl font-black text-white leading-none tracking-tighter uppercase">Automated <br/> <span className="text-primary-500">Matrix Protection</span></h1>
                            <button onClick={() => setPage('car-flow')} className="mt-6 px-8 py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-widest w-fit shadow-xl shadow-primary-500/30 active:scale-95 transition-transform">Get Quote</button>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div onClick={() => setPage('products')} className="p-8 glass-card rounded-[3rem] text-left border border-black/5 dark:border-white/5 shadow-lg cursor-pointer hover:scale-[1.02] transition-transform">
                            <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-6"><Grid size={28}/></div>
