const CarInsuranceFlow = ({ onExit }: { onExit: () => void }) => {
  const [step, setStep] = useState<CarInsuranceStep>(CarInsuranceStep.VEHICLE_DATA);
  const [vehicle, setVehicle] = useState<VehicleState>({
    brand: '', model: '', isOther: false, year: 2024, price: 0, manualPrice: false, plate: '', region: '2',
    usage: 'PRIVATE', condition: 'NEW', insuranceType: InsuranceType.COMPREHENSIVE,
    expansions: { flood: false, earthquake: false, srcc: false, terrorism: false, authorizedWorkshop: true, tpl: 0, paDriver: false, paPassenger: false },
    promoCode: '', discount: 0, discountType: 'PERCENT', selectedProvider: null,
    photos: { stnk: null, carFront: null, carBack: null, carLeft: null, carRight: null, interior: null }
  });
  const [user, setUser] = useState<UserState>({
    name: '', ktpNo: '', email: '', phone: '', address: '', recipientName: '', deliveryMethod: 'EMAIL', ktpPhoto: null
  });
  const [loading, setLoading] = useState(false);
  const [verifying, setVerifying] = useState(false);

  // Helper: Calculate Premium
  const calculateTotalPremium = (v: VehicleState, provider: Provider | null) => {
    if (!provider) return 0;
    const priceMillions = v.price / 1000000;
    const baseRate = getOJKRate(priceMillions, v.region, v.insuranceType);
    let totalRate = baseRate;

    if (v.expansions.flood) totalRate += EXPANSION_RATES.FLOOD;
    if (v.expansions.earthquake) totalRate += EXPANSION_RATES.EARTHQUAKE;
    if (v.expansions.srcc) totalRate += (EXPANSION_RATES.SRCC as any)[v.insuranceType];
    if (v.expansions.terrorism) totalRate += (EXPANSION_RATES.TERRORISM as any)[v.insuranceType];
    if (v.expansions.authorizedWorkshop) totalRate += 0.2; 

    let premium = (totalRate / 100) * v.price;
    premium += v.expansions.tpl * 1000000; 

    const total = premium + provider.adminFee + STAMP_DUTY;
    return total;
  };

  const handleFileUpload = (field: keyof VehiclePhotos | 'ktp', e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      if (field === 'ktp') {
          setUser({ ...user, ktpPhoto: base64 });
          setLoading(true);
          const res = await extractKtpData(base64);
          if (res.success) {
              setUser(prev => ({ ...prev, name: res.data.nama || '', ktpNo: res.data.noKtp || prev.ktpNo, address: res.data.alamat || prev.address }));
          }
          setLoading(false);
      } else if (field === 'stnk') {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
          setLoading(true);
          const res = await extractStnkData(base64);
          if (res.success) {
              // Extract logic
          }
          setLoading(false);
      } else {
          setVehicle({ ...vehicle, photos: { ...vehicle.photos, [field]: base64 } });
      }
    };
    reader.readAsDataURL(file);
  };

  const renderStepContent = () => {
    switch(step) {
      case CarInsuranceStep.VEHICLE_DATA:
        return (
          <form onSubmit={(e) => { e.preventDefault(); setStep(CarInsuranceStep.COVERAGE); }} className="space-y-8 animate-fade-in p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Data <span className="text-primary-500">Kendaraan</span></h2>
            <div className="space-y-4">
               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Merk Mobil</label>
                  <select 
                    className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white"
                    value={vehicle.brand}
                    onChange={e => setVehicle({ ...vehicle, brand: e.target.value, isOther: e.target.value === 'OTHERS', model: '' })}
                  >
                    <option value="">Pilih Merk</option>
                    {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).map(b => <option key={b} value={b}>{b}</option>)}
                    <option value="OTHERS">Others (Freetype)</option>
                  </select>
               </div>
               <div>
                  <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Model / Tipe</label>
                  {!vehicle.isOther ? (
                    <select 
                        className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white"
                        value={vehicle.model}
                        onChange={e => {
                            const modelData = CAR_DATABASE.find(c => c.code === e.target.value);
                            if (modelData) setVehicle({ ...vehicle, model: modelData.code, price: (modelData.yearPrices[vehicle.year] || 0) * 1000000 });
                        }}
                    >
                        <option value="">Pilih Model</option>
                        {CAR_DATABASE.filter(c => c.brand === vehicle.brand).map(c => <option key={c.code} value={c.code}>{c.modelName}</option>)}
                    </select>
                  ) : (
                    <input placeholder="Input Model" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl outline-none dark:text-white" onChange={e => setVehicle({...vehicle, model: e.target.value})} />
                  )}
               </div>
               <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Tahun</label>
                    <input type="number" className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl dark:text-white" value={vehicle.year} onChange={e => setVehicle({...vehicle, year: parseInt(e.target.value)})} />
                  </div>
                  <div>
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-2">Plat Nomor</label>
                    <input className="w-full p-4 bg-gray-100 dark:bg-white/5 rounded-2xl uppercase dark:text-white" value={vehicle.plate} onChange={e => setVehicle({...vehicle, plate: e.target.value})} placeholder="B-123-XYZ" />
                  </div>
               </div>
            </div>
            <button type="submit" className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-[0.2em] shadow-xl">Lanjutkan</button>
          </form>
        );
      case CarInsuranceStep.COVERAGE:
        return (
          <form onSubmit={(e) => { e.preventDefault(); setStep(CarInsuranceStep.SELECT_PROVIDER); }} className="space-y-8 animate-fade-in p-6">
            <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Jenis <span className="text-primary-500">Perlindungan</span></h2>
            <div className="grid grid-cols-2 gap-4">
                {[InsuranceType.COMPREHENSIVE, InsuranceType.TLO].map(type => (
                    <button key={type} type="button" onClick={() => setVehicle({...vehicle, insuranceType: type})} className={`p-6 rounded-3xl border-2 transition-all ${vehicle.insuranceType === type ? 'border-primary-500 bg-primary-500/5' : 'border-gray-200 dark:border-white/10'}`}>
                        <p className="font-black text-xs uppercase dark:text-white">{type}</p>
                    </button>
                ))}
            </div>
            <button type="submit" className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-[0.2em]">Cari Penawaran</button>
          </form>
        );
      case CarInsuranceStep.SELECT_PROVIDER:
        return (
            <div className="p-6 space-y-10 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Pilih <span className="text-primary-500">Partner</span></h2>
                <div className="grid gap-6">
                    {INSURANCE_PROVIDERS.map(p => (
                        <div key={p.id} className="p-8 glass-card rounded-[3rem] border border-black/5 dark:border-white/5 space-y-6">
                            <div className="flex items-center justify-between">
                                <div className="flex items-center gap-4">
                                    <div className="w-12 h-12 bg-primary-500 text-white rounded-2xl flex items-center justify-center"><p.logo size={24}/></div>
                                    <h4 className="font-black text-xl uppercase tracking-tighter dark:text-white">{p.name}</h4>
                                </div>
                                <div className="text-right">
                                    <p className="text-[0.55rem] font-black text-gray-400 uppercase tracking-widest">Premi Tahunan</p>
                                    <p className="text-2xl font-black text-primary-500">{formatIDR(calculateTotalPremium(vehicle, p))}</p>
                                </div>
                            </div>
                            <button onClick={() => { setVehicle({ ...vehicle, selectedProvider: p }); setStep(CarInsuranceStep.KYC_UPLOAD); }} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs">Pilih Paket</button>
                        </div>
                    ))}
                </div>
            </div>
        );
      case CarInsuranceStep.KYC_UPLOAD:
        return (
            <div className="p-6 space-y-8 animate-fade-in">
                <h2 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Data <span className="text-primary-500">Nasabah</span></h2>
                <div className="aspect-video relative rounded-3xl overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer">
                    {user.ktpPhoto ? <img src={user.ktpPhoto} className="w-full h-full object-cover" /> : <><Camera size={48} className="text-gray-400 group-hover:text-primary-500"/><p className="text-[0.65rem] font-black uppercase text-gray-400 mt-2">Upload Foto KTP</p></>}
                    <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={e => handleFileUpload('ktp', e)} />
                </div>
                <button onClick={() => setStep(CarInsuranceStep.SUCCESS)} className="w-full py-5 bg-primary-500 text-white rounded-3xl font-black uppercase tracking-widest">Selesaikan Pembelian</button>
            </div>
        );
      case CarInsuranceStep.SUCCESS:
        return (
            <div className="p-6 text-center space-y-10 py-20 animate-fade-in">
                <div className="w-24 h-24 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl animate-pop-in"><Check size={48} strokeWidth={4}/></div>
                <h2 className="text-4xl font-black uppercase dark:text-white">Link <span className="text-primary-500">Established</span></h2>
                <p className="text-gray-500 dark:text-gray-400">Polis digital Anda telah dikirimkan ke email terdaftar.</p>
                <button onClick={onExit} className="w-full py-5 bg-gray-900 dark:bg-white dark:text-black text-white rounded-3xl font-black uppercase tracking-widest mt-10">Kembali ke Base</button>
            </div>
        );
      default: return null;
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-dark-bg text-gray-900 dark:text-white pb-32">
        <header className="h-20 glass-card px-6 flex items-center justify-between border-b border-black/5 dark:border-white/5">
            <button onClick={onExit} className="w-10 h-10 bg-gray-100 dark:bg-white/5 rounded-xl flex items-center justify-center text-gray-500"><ChevronLeft size={24}/></button>
            <div className="flex items-center gap-2"><div className="w-8 h-8 bg-primary-500 rounded-lg flex items-center justify-center text-white"><Car size={18}/></div><span className="font-black text-sm uppercase tracking-widest dark:text-white">Car Insurance</span></div>
            <div className="w-10"></div>
        </header>
        <main className="max-w-lg mx-auto">{renderStepContent()}</main>
    </div>
  );
};

