                            <button onClick={() => setPage('car-flow')} className="mt-6 px-8 py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-widest w-fit shadow-xl shadow-primary-500/30 active:scale-95 transition-transform">Get Quote</button>
                        </div>
                    </div>
                    <div className="grid grid-cols-2 gap-4">
                        <div onClick={() => setPage('products')} className="p-8 glass-card rounded-[3rem] text-left border border-black/5 dark:border-white/5 shadow-lg cursor-pointer hover:scale-[1.02] transition-transform">
                            <div className="w-14 h-14 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-6"><Grid size={28}/></div>
                            <p className="font-black text-2xl uppercase tracking-tighter leading-none dark:text-white">Neural <br/> Store</p>
