                    <div className="grid gap-10">
                        {PRODUCT_LIST.map(p => (
                            <div key={p.id} onClick={() => p.id === 'car' && setPage('car-flow')} className="p-8 glass-card rounded-[3rem] border border-black/5 dark:border-white/5 shadow-xl cursor-pointer group hover:-translate-y-2 transition-transform">
