                                    <p className="text-xs italic font-bold text-slate-600 dark:text-slate-300 leading-relaxed">"{p.aiSummary}"</p>
                                </div>
                            </div>
                        ))}
                    </div>

                    <div className="pt-12 space-y-6">
                        <h3 className="text-xl font-black uppercase tracking-tight dark:text-white">Upcoming <span className="text-primary-500">Innovations</span></h3>
                        <div className="grid grid-cols-2 gap-4">
                            {UPCOMING_PRODUCTS.map(p => (
                                <div key={p.id} className="p-6 glass-card rounded-[2.5rem] border border-black/5 dark:border-white/5 flex flex-col items-center opacity-70 group relative overflow-hidden">
