const AuthGateway = ({ onLogin, darkMode }: { onLogin: (role: string, email: string) => void, darkMode: boolean }) => {
  const [email, setEmail] = useState(localStorage.getItem('rememberedEmail') || '');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);

  const handleLoginSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setTimeout(() => {
      localStorage.setItem('rememberedEmail', email);
      setLoading(false);
      onLogin('Member', email);
    }, 1500);
  };

  return (
    <div className={`fixed inset-0 z-[200] flex flex-col items-center justify-center p-6 ${darkMode ? 'bg-dark-bg' : 'bg-slate-50'}`}>
      <div className="relative w-full max-w-md glass-card rounded-[3.5rem] p-12 shadow-2xl border border-white/20 animate-pop-in">
