               <h1 className="font-black text-3xl tracking-tighter uppercase dark:text-white">Sure<span className="text-primary-500">Path</span></h1>
            </div>
            <form onSubmit={handleLoginSubmit} className="space-y-4">
              <input type="email" placeholder="EMAIL" className="w-full p-4 bg-slate-100/50 dark:bg-white/5 rounded-2xl outline-none dark:text-white" value={email} onChange={e => setEmail(e.target.value)} />
              <input type="password" placeholder="PASSWORD" className="w-full p-4 bg-slate-100/50 dark:bg-white/5 rounded-2xl outline-none dark:text-white" value={password} onChange={e => setPassword(e.target.value)} />
