                        <div className="absolute inset-0 bg-gradient-to-t from-black/95 via-black/40 to-transparent p-12 flex flex-col justify-end">
                            <p className="text-[0.6rem] font-bold text-primary-400 uppercase tracking-[0.5em] mb-2">Neural Protection 3.0</p>
                            <h1 className="text-4xl font-black text-white leading-none tracking-tighter uppercase">Automated <br/> <span className="text-primary-500">Protection</span></h1>
                            <button onClick={() => setPage('products')} className="mt-6 px-8 py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-widest w-fit shadow-xl">Get Quote</button>
                        </div>
                    </div>
                </div>
            )}

            {currentPage === 'products' && (
                <div className="space-y-12 animate-fade-in">
                    <div className="space-y-2">
                        <h2 className="text-4xl font-black uppercase tracking-tighter dark:text-white">Neural <span className="text-primary-500">Store</span></h2>
                        <p className="text-gray-400 font-medium text-sm tracking-wide">Pilih perlindungan cerdas untuk setiap aspek kehidupan Anda.</p>
                    </div>
                    <div className="grid gap-8">
                        {PRODUCT_LIST.map(p => (
                            <div key={p.id} className="p-8 glass-card rounded-[3rem] border border-black/5 dark:border-white/5 shadow-xl cursor-pointer group hover:scale-[1.02] transition-all">
                                <div className="flex items-center justify-between mb-6">
                                    <div className={`w-16 h-16 ${p.bg} ${p.color} rounded-2xl flex items-center justify-center`}><p.icon size={32}/></div>
                                    <div className="text-right">
                                        <div className="flex text-amber-500 gap-0.5"><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/><Star size={12} fill="currentColor"/></div>
                                        <p className="text-[0.6rem] font-bold text-gray-400 mt-1 uppercase tracking-widest">{p.rating} / 5.0</p>
                                    </div>
                                </div>
                                <h4 className="font-black text-2xl uppercase tracking-tighter dark:text-white">{p.title}</h4>
                                <p className="text-sm text-gray-500 dark:text-gray-400 font-medium mb-6 mt-2">{p.description}</p>
                                <div className="p-5 bg-primary-500/5 dark:bg-primary-500/10 rounded-[2rem] border border-primary-500/20 space-y-3">
                                    <div className="flex items-center gap-2">
                                        <Sparkles size={14} className="text-primary-500 animate-pulse"/>
                                        <p className="text-[0.65rem] font-black uppercase text-primary-500 tracking-widest">AI Consensus Insight</p>
                                    </div>
                                    <p className="text-xs italic font-bold text-slate-600 dark:text-slate-300">"{p.aiSummary}"</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {currentPage === 'claim' && (
                <div className="space-y-10 animate-fade-in">
                    <div className="space-y-2">
                        <h2 className="text-4xl font-black uppercase tracking-tighter dark:text-white">
                            {claimFlowStep === 'upload' && 'Snap Damage'}
                            {claimFlowStep === 'report' && 'Neural Analysis'}
                            {claimFlowStep === 'chronology' && 'Detail Kejadian'}
                            {claimFlowStep === 'insurance' && 'Pilih Asuransi'}
                            {claimFlowStep === 'docs' && 'Unggah Dokumen'}
                        </h2>
                        <p className="text-gray-400 font-medium text-sm">
                            {claimFlowStep === 'upload' && 'Upload bukti foto untuk audit neural instan.'}
                            {claimFlowStep === 'chronology' && 'Lengkapi kronologi untuk memproses laporan klaim.'}
                            {claimFlowStep === 'insurance' && 'Pilih asuransi rekanan tempat polis Anda terdaftar.'}
                        </p>
                    </div>

                    {isAnalyzingClaim && (
                        <div className="glass-card rounded-[3.5rem] p-12 border-2 border-primary-500/20">
                            <InformativeNeuralLoader messages={["Scanning Chassis...", "Calculating Severity...", "Verifying Policy Matrix..."]} />
                        </div>
                    )}

                    {!isAnalyzingClaim && claimFlowStep === 'upload' && (
                        <div className="aspect-square relative rounded-[4rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
                            <Camera size={64} className="text-gray-400 group-hover:text-primary-500 transition-all"/>
                            <p className="text-xl font-black uppercase text-gray-400 mt-4 group-hover:text-primary-500">Mulai Scan</p>
                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleClaimFileUpload} />
                        </div>
                    )}

                    {claimFlowStep === 'report' && claimResult && (
                        <div className="space-y-8 animate-pop-in">
                            <div className="p-8 glass-card rounded-[3.5rem] border border-primary-500/20 shadow-2xl overflow-hidden relative bg-primary-500/5">
                                <div className="absolute top-0 right-0 p-8">
                                    <span className="px-4 py-2 rounded-2xl bg-primary-500 text-white font-black text-[0.6rem] uppercase tracking-widest">{claimResult.severity}</span>
                                </div>
                                <div className="space-y-4">
                                    <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">Total Neural Estimate</p>
                                    <h4 className="text-5xl font-black text-primary-500 tracking-tighter">{formatIDR(claimResult.totalEstimasi)}</h4>
                                    <p className="text-sm font-bold text-gray-600 dark:text-gray-300 italic leading-relaxed">"{claimResult.aiInsight}"</p>
                                </div>
                            </div>
                            <div className="space-y-4">
                                <button 
                                    onClick={() => setClaimFlowStep('chronology')}
                                    className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.2em] shadow-xl hover:scale-105 transition-transform"
                                >
                                    Laporkan Klaim
                                </button>
                                <button onClick={resetClaim} className="w-full text-center text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">Batal & Scan Ulang</button>
                            </div>
                        </div>
                    )}

                    {claimFlowStep === 'chronology' && (
                        <div className="space-y-6 animate-fade-in">
                            <div className="space-y-4">
                                <div className="relative">
                                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-4 mb-2 block">Tipe Kejadian</label>
                                    <div className="grid grid-cols-3 gap-2">
                                        {['TABRAKAN', 'KEHILANGAN', 'BENCANA'].map(t => (
                                            <button 
                                                key={t}
                                                onClick={() => setClaimDetails({...claimDetails, type: t})}
                                                className={`py-3 rounded-2xl text-[0.6rem] font-black uppercase border-2 transition-all ${claimDetails.type === t ? 'border-primary-500 bg-primary-500/10 text-primary-500' : 'border-gray-100 dark:border-white/10 text-gray-400'}`}
                                            >
                                                {t}
                                            </button>
                                        ))}
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="space-y-2">
                                        <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-4">Tanggal Kejadian</label>
                                        <div className="relative">
                                            <Calendar size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                                            <input type="date" className="w-full p-4 pl-12 bg-gray-100 dark:bg-white/5 rounded-2xl font-bold dark:text-white outline-none" value={claimDetails.date} onChange={e => setClaimDetails({...claimDetails, date: e.target.value})} />
                                        </div>
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-4">Lokasi Kejadian</label>
                                        <div className="relative">
                                            <MapPinned size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400" />
                                            <input placeholder="Contoh: Tol JORR" className="w-full p-4 pl-12 bg-gray-100 dark:bg-white/5 rounded-2xl font-bold dark:text-white outline-none" value={claimDetails.location} onChange={e => setClaimDetails({...claimDetails, location: e.target.value})} />
                                        </div>
                                    </div>
                                </div>
                                <div className="space-y-2">
                                    <label className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest ml-4">Kronologis Lengkap</label>
                                    <textarea 
                                        placeholder="Ceritakan kejadian secara detail..." 
                                        className="w-full p-6 bg-gray-100 dark:bg-white/5 rounded-[2rem] font-medium text-sm dark:text-white outline-none h-40 resize-none"
                                        value={claimDetails.chronology}
                                        onChange={e => setClaimDetails({...claimDetails, chronology: e.target.value})}
                                    />
                                </div>
                            </div>
                            <button 
                                onClick={() => setClaimFlowStep('insurance')}
                                disabled={!claimDetails.date || !claimDetails.location || !claimDetails.chronology}
                                className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.2em] shadow-xl disabled:opacity-50"
                            >
                                Pilih Asuransi
                            </button>
                        </div>
                    )}

                    {claimFlowStep === 'insurance' && (
                        <div className="space-y-6 animate-fade-in">
                            <div className="grid gap-4">
                                {[
                                    { id: 'intra', name: 'Intra Asia', tag: 'Fast Document Audit', icon: ShieldCheck },
                                    { id: 'zurich', name: 'Zurich Insurance', tag: 'Premium Roadside Service', icon: ShieldPlus },
                                    { id: 'tugu', name: 'Tugu Insurance', tag: 'Digital Claim Specialist', icon: Zap }
                                ].map(ins => (
                                    <div 
                                        key={ins.id}
                                        onClick={() => setClaimDetails({...claimDetails, selectedInsuranceId: ins.id})}
                                        className={`p-6 rounded-[2.5rem] border-2 cursor-pointer transition-all flex items-center justify-between group ${claimDetails.selectedInsuranceId === ins.id ? 'border-primary-500 bg-primary-500/10' : 'border-gray-100 dark:border-white/10 hover:border-primary-500/30'}`}
                                    >
                                        <div className="flex items-center gap-4">
                                            <div className={`w-12 h-12 rounded-2xl flex items-center justify-center ${claimDetails.selectedInsuranceId === ins.id ? 'bg-primary-500 text-white' : 'bg-gray-100 dark:bg-white/5 text-gray-400 group-hover:text-primary-500'}`}>
                                                <ins.icon size={24} />
                                            </div>
                                            <div>
                                                <h4 className="font-black uppercase text-sm dark:text-white">{ins.name}</h4>
                                                <p className="text-[0.6rem] font-bold text-primary-500 uppercase tracking-widest">{ins.tag}</p>
                                            </div>
                                        </div>
                                        {claimDetails.selectedInsuranceId === ins.id && <div className="w-6 h-6 bg-primary-500 rounded-full flex items-center justify-center text-white"><Check size={14} strokeWidth={4} /></div>}
                                    </div>
                                ))}
                            </div>
                            <button 
                                onClick={() => setClaimFlowStep('docs')}
                                disabled={!claimDetails.selectedInsuranceId}
                                className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.2em] shadow-xl disabled:opacity-50"
                            >
                                Lanjut Unggah Dokumen
                            </button>
                        </div>
                    )}

                    {claimFlowStep === 'docs' && (
                        <div className="space-y-8 animate-fade-in">
                            <div className="space-y-6">
                                <div className="p-8 rounded-[3rem] bg-gray-100 dark:bg-white/5 border-2 border-dashed border-gray-300 dark:border-white/10 relative overflow-hidden group">
                                    {claimDetails.policyFile ? (
                                        <div className="flex flex-col items-center gap-4 py-4">
                                            <div className="w-16 h-16 bg-emerald-500/10 rounded-2xl flex items-center justify-center text-emerald-500"><FileText size={32}/></div>
                                            <p className="font-bold text-sm">Dokumen Polis Berhasil Diunggah</p>
                                            <button onClick={() => setClaimDetails({...claimDetails, policyFile: null})} className="text-[0.6rem] font-black uppercase text-rose-500 underline">Ganti File</button>
                                        </div>
                                    ) : (
                                        <div className="flex flex-col items-center gap-4 py-4">
                                            <FileUp size={48} className="text-gray-400 group-hover:text-primary-500 transition-colors" />
                                            <div className="text-center">
                                                <p className="font-black text-sm uppercase tracking-tight dark:text-white">Unggah Dokumen Polis</p>
                                                <p className="text-[0.6rem] text-gray-400 mt-1 uppercase">Format PDF/JPG (Maks 5MB)</p>
                                            </div>
                                            <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handlePolicyUpload} />
                                        </div>
                                    )}
                                </div>
                            </div>
                            <button 
                                onClick={() => setClaimFlowStep('success')}
                                disabled={!claimDetails.policyFile}
                                className="w-full py-6 bg-primary-500 text-white rounded-[2.5rem] font-black uppercase tracking-[0.2em] shadow-xl disabled:opacity-50"
                            >
                                Kirim Laporan Klaim
                            </button>
                        </div>
                    )}

                    {claimFlowStep === 'success' && (
                        <div className="text-center space-y-10 py-10 animate-pop-in">
                            <div className="w-32 h-32 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl shadow-emerald-500/40">
                                <CheckCircle2 size={64} strokeWidth={3} />
                            </div>
                            <div className="space-y-4">
                                <h3 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Laporan <span className="text-primary-500">Diterima</span></h3>
                                <p className="text-sm text-gray-500 dark:text-gray-400 px-6 leading-relaxed">Klaim Anda sedang diproses secara real-time melalui jaringan neural asuransi kami.</p>
                            </div>
                            <button onClick={() => { setPage('home'); resetClaim(); }} className="w-full py-5 bg-gray-900 dark:bg-white dark:text-black text-white rounded-3xl font-black uppercase tracking-widest shadow-xl">Kembali ke Home</button>
                        </div>
                    )}
                </div>
            )}

            {currentPage === 'wallet' && (
                <div className="space-y-10 animate-fade-in">
                    <h2 className="text-4xl font-black uppercase tracking-tighter dark:text-white">Neural <span className="text-primary-500">Wallet</span></h2>
                    <div className="p-10 bg-gray-900 dark:bg-white rounded-[4rem] text-white dark:text-black shadow-2xl relative overflow-hidden group">
                        <div className="absolute top-0 right-0 p-10 opacity-10 group-hover:opacity-20 transition-opacity"><Coins size={80}/></div>
                        <p className="text-[0.65rem] font-black uppercase tracking-[0.3em] opacity-60">Balance Matrix</p>
                        <h3 className="text-5xl font-black tracking-tighter mt-2 tabular-nums">Rp 14.250.000</h3>
                        <div className="mt-8 flex gap-4">
                            <button className="bg-primary-500 text-white px-8 py-3 rounded-2xl font-black uppercase text-[0.6rem] tracking-widest">Withdraw</button>
                            <button className="bg-white/10 dark:bg-gray-100 px-8 py-3 rounded-2xl font-black uppercase text-[0.6rem] tracking-widest">Top Up</button>
                        </div>
                    </div>
                </div>
            )}

            {currentPage === 'profile' && (
                <div className="text-center space-y-10 animate-fade-in">
                    <div className="relative inline-block">
                        <div className="w-32 h-32 rounded-[3rem] border-4 border-primary-500/20 p-1.5 mx-auto">
                            <div className="w-full h-full rounded-[2.5rem] overflow-hidden bg-gray-100 dark:bg-white/5">
                                <img src={`https://i.pravatar.cc/150?u=${user?.email}`} className="w-full h-full object-cover" />
                            </div>
                        </div>
                        <div className="absolute -bottom-2 -right-2 bg-emerald-500 text-white w-10 h-10 rounded-2xl flex items-center justify-center border-4 border-white dark:border-dark-bg"><ShieldCheck size={20}/></div>
                    </div>
                    <div>
                        <h3 className="text-3xl font-black uppercase tracking-tighter dark:text-white">Ahmad Sholihin</h3>
                        <p className="text-xs font-black text-primary-500 uppercase tracking-[0.4em] mt-2">Matrix Verified</p>
                    </div>
                    <button onClick={() => { setIsLoggedIn(false); setPage('home'); }} className="w-full py-5 bg-rose-500/10 text-rose-500 rounded-3xl font-black uppercase text-xs tracking-widest flex items-center justify-center gap-2">
                        <LogOut size={18}/> Terminate Session
                    </button>
                </div>
            )}
        </main>

        <nav className="fixed bottom-6 inset-x-4 h-20 glass-card z-50 flex items-center justify-around px-2 rounded-[2.5rem] shadow-2xl border border-black/5 dark:border-white/10 max-w-lg mx-auto">
            {[
                { id: 'home', icon: Home, label: 'Home' },
                { id: 'products', icon: Grid, label: 'Products' },
                { id: 'claim', icon: Zap, label: 'Claim AI' },
                { id: 'wallet', icon: Wallet, label: 'Wallet' },
                { id: 'profile', icon: User, label: 'Profile' }
            ].map(item => (
                <button key={item.id} onClick={() => setPage(item.id)} className={`relative flex flex-col items-center gap-1 flex-1 py-2 transition-all ${currentPage === item.id ? 'text-primary-500 scale-110' : 'text-gray-400 hover:text-gray-600 dark:hover:text-gray-200'}`}>
                    <item.icon size={22} strokeWidth={currentPage === item.id ? 2.5 : 2} className={currentPage === item.id && item.id === 'claim' ? 'animate-pulse' : ''} />
                    <span className="text-[0.5rem] font-black uppercase tracking-widest">{item.label}</span>
                </button>
            ))}
        </nav>
    </div>
  );
};

export default App;
